insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('citas-consultorio','salud','{}'::text[],'Menos citas perdidas en un consultorio','Explora cómo diseñar recordatorios y reprogramaciones para un consultorio pequeño, probándolos con un caso simulado.','Prototipo','~15 h',15,array['Procesos','Atención al paciente']::text[],array['resolver','crear']::text[],'ficticios',null,'medicina enfermeria psicologia ingenieria de sistemas ingenieria industrial administracion mapeo de procesos redaccion clara para pacientes analisis basico de datos hoja de calculo diagramas de flujo mensajeria o correo para la simulacion',$ff4af0d${"id": "citas-consultorio", "area": "salud", "areas2": [], "titulo": "Menos citas perdidas en un consultorio", "resumen": "Explora cómo diseñar recordatorios y reprogramaciones para un consultorio pequeño, probándolos con un caso simulado.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Procesos", "Atención al paciente"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: puedes hacerlo sin pedir permiso a nadie", "carreras": ["Medicina", "Enfermería", "Psicología", "Ingeniería de Sistemas", "Ingeniería Industrial", "Administración"], "problema": ["Cuando un paciente falta a su cita sin avisar, se pierde un espacio que otra persona pudo usar y el consultorio pierde tiempo y dinero."], "desarrollar": ["Un flujo de recordatorios antes de la cita, una forma fácil de confirmar o reprogramar, y un registro simple de cuántas citas se recuperan. Se puede probar con datos inventados."], "ampliaciones": [{"titulo": "Otro público", "aporta": "Explora cómo adaptar los mensajes para personas mayores o que casi no usan el celular."}, {"titulo": "Otra mirada", "aporta": "Descubre cuánto tiempo y dinero se pierde por cada cita que nadie ocupa, y qué ahorro traería recuperarla."}, {"titulo": "Otro formato", "aporta": "Imagina una forma de reprogramar la cita desde un enlace, sin llamar a nadie."}], "objetivos": ["Describir cómo se agenda y se confirma una cita hoy.", "Diseñar los mensajes y el momento en que se envían.", "Medir con un caso simulado cuántas citas se podrían recuperar."], "habilidades": ["Mapeo de procesos", "Redacción clara para pacientes", "Análisis básico de datos"], "herramientas": ["Hoja de cálculo", "Diagramas de flujo", "Mensajería o correo para la simulación"], "lineamientos": ["Usa datos ficticios: nunca información real de pacientes.", "Los mensajes deben ser breves y respetuosos.", "Aclara que es una simulación y no un servicio médico."], "otroSector": "Sirve igual para peluquerías, academias, talleres mecánicos o cualquier negocio que trabaje con citas."}$ff4af0d$::jsonb,0),
('que-aparato-de-tu-casa-se-lleva-la-mayor-parte-de-tu-recibo-de-l','ambiente',array['ciencias']::text[],'¿Qué aparato de tu casa se lleva la mayor parte de tu recibo de luz?','Explora cómo estimar el consumo eléctrico de los dispositivos que utilizas a diario para descubrir cuáles tienen un mayor impacto en el gasto energético y qué cambios podrían ayudarte a utilizar la energía de forma más eficiente.','Análisis','~12 h',12,array['Energía','Datos']::text[],array['investigar','resolver','otro-sector']::text[],'propios',null,'ingenieria electrica ingenieria electronica ingenieria de sistemas ingenieria industrial ingenieria ambiental estadistica economia administracion recoleccion y analisis de datos. interpretacion de informacion tecnica. visualizacion de datos. pensamiento critico. comunicacion de resultados. hoja de calculo. calculadoras de consumo energetico. especificaciones tecnicas de equipos. herramientas de graficos y visualizacion.',$f20e78b${"id": "que-aparato-de-tu-casa-se-lleva-la-mayor-parte-de-tu-recibo-de-l", "area": "ambiente", "areas2": ["ciencias"], "titulo": "¿Qué aparato de tu casa se lleva la mayor parte de tu recibo de luz?", "resumen": "Explora cómo estimar el consumo eléctrico de los dispositivos que utilizas a diario para descubrir cuáles tienen un mayor impacto en el gasto energético y qué cambios podrían ayudarte a utilizar la energía de forma más eficiente.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Energía", "Datos"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias o públicos: puedes utilizar especificaciones técnicas de los equipos que tienes en casa o recopilar información de fabricantes y fuentes abiertas.", "carreras": ["Ingeniería Eléctrica", "Ingeniería Electrónica", "Ingeniería de Sistemas", "Ingeniería Industrial", "Ingeniería Ambiental", "Estadística", "Economía", "Administración"], "problema": ["La mayoría de las personas sabe cuánto paga por electricidad cada mes, pero pocas conocen cuánto consume realmente cada aparato que utilizan. Un televisor, una computadora, un ventilador o un cargador pueden formar parte de la rutina diaria sin que exista una idea clara de cuánto representan dentro del consumo total.", "Esta falta de información dificulta tomar decisiones informadas. Muchas veces se intenta ahorrar energía cambiando hábitos que tienen poco impacto, mientras que otros dispositivos con consumos mucho mayores pasan desapercibidos.", "Comprender cómo se distribuye el consumo permite identificar oportunidades de ahorro, comparar alternativas y utilizar los recursos de manera más eficiente."], "desarrollar": ["Selecciona varios equipos de uso habitual y estima su consumo utilizando información técnica, horas de uso aproximadas y registros sencillos.", "Con esos datos, elabora tablas o gráficos que permitan comparar dispositivos, identificar cuáles consumen más energía y estimar cuánto representan dentro de un periodo determinado.", "El resultado puede presentarse como un informe visual, una hoja de cálculo interactiva o un pequeño panel informativo."], "ampliaciones": [{"titulo": "Comparar escenarios", "aporta": "descubre cómo cambiaría el consumo si algunos equipos se utilizaran menos tiempo o fueran reemplazados por alternativas más eficientes."}, {"titulo": "Analizar costos", "aporta": "estima cuánto dinero representa el consumo de los distintos dispositivos a lo largo de un mes o un año."}, {"titulo": "Diseñar recomendaciones", "aporta": "crea una guía sencilla con hábitos que ayuden a reducir el gasto energético sin afectar significativamente la comodidad de las personas."}], "objetivos": ["Identificar qué información se necesita para estimar el consumo de un dispositivo.", "Registrar y organizar datos de uso de manera sistemática.", "Comparar distintos equipos mediante métricas comunes.", "Visualizar resultados de forma clara y comprensible.", "Proponer recomendaciones basadas en evidencia."], "habilidades": ["Recolección y análisis de datos.", "Interpretación de información técnica.", "Visualización de datos.", "Pensamiento crítico.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Calculadoras de consumo energético.", "Especificaciones técnicas de equipos.", "Herramientas de gráficos y visualización."], "lineamientos": ["Utiliza información verificable y documenta siempre de dónde provienen los datos. Cuando no sea posible conocer el consumo exacto, indica claramente las estimaciones y los supuestos utilizados.", "Recuerda que el objetivo del proyecto es comprender patrones de consumo y no obtener una medición de laboratorio. La transparencia en los cálculos es más importante que la precisión absoluta."], "otroSector": "La misma metodología puede aplicarse al análisis del consumo de agua, combustible, materiales de oficina o cualquier otro recurso cuyo uso pueda registrarse y compararse mediante datos."}$f20e78b$::jsonb,0),
('donde-hace-mas-calor-en-tu-centro-de-estudios-y-por-que','ambiente',array['ciudades']::text[],'¿Dónde hace más calor en tu centro de estudios y por qué?','Explora cómo cambia la sensación de calor entre diferentes zonas de un mismo espacio, por qué algunas áreas se calientan más que otras y qué podría hacerse para que sean más cómodas.','Análisis','~15 h',15,array['Datos','Ambiente','Mediciones']::text[],array['investigar','resolver','otro-sector']::text[],'propios',null,'ingenieria ambiental arquitectura ingenieria civil fisica estadistica ciencia de datos ingenieria de sistemas biologia diseno de mediciones y toma de datos. analisis y visualizacion de datos. pensamiento cientifico. interpretacion de graficos y mapas. comunicacion de resultados. termometro u otro instrumento de medicion sencillo. hoja de calculo. herramientas de graficos y mapas. camara o cuaderno de campo para registrar las condiciones de cada punto. herramientas de programacion si deseas automatizar el analisis.',$fe3a8f8${"id": "donde-hace-mas-calor-en-tu-centro-de-estudios-y-por-que", "area": "ambiente", "areas2": ["ciudades"], "titulo": "¿Dónde hace más calor en tu centro de estudios y por qué?", "resumen": "Explora cómo cambia la sensación de calor entre diferentes zonas de un mismo espacio, por qué algunas áreas se calientan más que otras y qué podría hacerse para que sean más cómodas.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Datos", "Ambiente", "Mediciones"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias o ficticias: puedes medir la temperatura con un termómetro sencillo en distintos puntos de tu centro de estudios, o trabajar con datos simulados si no puedes salir a medir.", "carreras": ["Ingeniería Ambiental", "Arquitectura", "Ingeniería Civil", "Física", "Estadística", "Ciencia de Datos", "Ingeniería de Sistemas", "Biología"], "problema": ["En un mismo campus, parque o patio, la temperatura puede variar bastante de un punto a otro: una zona con cemento y sin sombra puede resultar mucho más calurosa que otra con árboles, césped o edificios que dan sombra. Sin embargo, rara vez se mide esa diferencia, y las decisiones sobre dónde poner bancas, áreas de descanso o actividades se toman por intuición.", "Esto afecta el confort, el uso de los espacios y, en días de calor intenso, el bienestar de las personas que pasan allí buena parte del día."], "desarrollar": ["Un análisis que elija entre 8 y 10 puntos de un mismo espacio, registre la temperatura a distintas horas durante varios días y anote las condiciones de cada punto, como sombra, tipo de superficie, vegetación y circulación de aire.", "El resultado puede ser un mapa sencillo con colores, un conjunto de gráficos comparativos o un informe que explique qué factores parecen influir más en el calor de cada zona."], "ampliaciones": [{"titulo": "Medición automática", "aporta": "explora cómo usar sensores económicos para registrar la temperatura de forma continua sin tener que estar presente."}, {"titulo": "Comparar superficies", "aporta": "analiza cuánto cambia la temperatura entre cemento, pasto, tierra y zonas bajo sombra."}, {"titulo": "Proponer mejoras", "aporta": "estima qué efecto podría tener añadir sombra, plantas o cambios de materiales y presenta una propuesta razonada."}], "objetivos": ["Diseñar un plan de medición con puntos, horarios y condiciones comparables.", "Registrar y organizar los datos de forma ordenada.", "Visualizar las diferencias entre zonas.", "Relacionar las diferencias con las características de cada lugar.", "Proponer recomendaciones basadas en la evidencia obtenida."], "habilidades": ["Diseño de mediciones y toma de datos.", "Análisis y visualización de datos.", "Pensamiento científico.", "Interpretación de gráficos y mapas.", "Comunicación de resultados."], "herramientas": ["Termómetro u otro instrumento de medición sencillo.", "Hoja de cálculo.", "Herramientas de gráficos y mapas.", "Cámara o cuaderno de campo para registrar las condiciones de cada punto.", "Herramientas de programación si deseas automatizar el análisis."], "lineamientos": ["Usa siempre el mismo instrumento y mide a las mismas horas para que los datos sean comparables. Protégete del sol durante las mediciones y no ingreses a zonas restringidas o sin autorización.", "Presenta los resultados como observaciones indicativas, no como mediciones científicas de alta precisión. Si deseas proponer cambios en un espacio, consulta antes con quienes lo administran."], "otroSector": "La misma metodología puede aplicarse a parques, colegios, mercados, patios industriales, estacionamientos, azoteas o espacios de espera al aire libre, y a la planificación de espacios públicos más cómodos."}$fe3a8f8$::jsonb,1),
('que-hacer-con-los-aparatos-electronicos-viejos-o-malogrados','ambiente',array['sociedad']::text[],'¿Qué hacer con los aparatos electrónicos viejos o malogrados?','Investiga qué ocurre con los celulares, cargadores, audífonos, laptops y otros aparatos que dejan de funcionar o de usarse, y cómo decidir entre repararlos, reutilizarlos, donarlos o desecharlos de forma responsable.','Investigación','3 a 6 semanas',27,array['Sostenibilidad','Electrónica','Economía circular']::text[],array['investigar','otro-sector']::text[],'propios',null,'ingenieria ambiental ingenieria electronica ingenieria industrial ingenieria de sistemas economia administracion ingenieria quimica analisis de ciclo de vida de productos. sostenibilidad y gestion de residuos. electronica basica. diseno de arboles de decision. analisis de costos y beneficios. comunicacion clara de informacion. hoja de calculo. herramientas de diagramas de flujo. mapas digitales para ubicar puntos de acopio. herramientas web basicas si deseas crear una guia interactiva.',$fd089ba${"id": "que-hacer-con-los-aparatos-electronicos-viejos-o-malogrados", "area": "ambiente", "areas2": ["sociedad"], "titulo": "¿Qué hacer con los aparatos electrónicos viejos o malogrados?", "resumen": "Investiga qué ocurre con los celulares, cargadores, audífonos, laptops y otros aparatos que dejan de funcionar o de usarse, y cómo decidir entre repararlos, reutilizarlos, donarlos o desecharlos de forma responsable.", "tipo": "Investigación", "tiempo": "3 a 6 semanas", "horas": 27, "etiquetas": ["Sostenibilidad", "Electrónica", "Economía circular"], "intencion": ["investigar", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes inventariar los aparatos que hay en tu casa, usar un hogar imaginario y revisar las opciones de reparación, donación o reciclaje que existan en tu zona.", "carreras": ["Ingeniería Ambiental", "Ingeniería Electrónica", "Ingeniería Industrial", "Ingeniería de Sistemas", "Economía", "Administración", "Ingeniería Química"], "problema": ["En casi todos los hogares hay un cajón o una caja con aparatos que ya no se usan: celulares antiguos, cables sueltos, baterías, controles, audífonos o computadoras que \"algún día\" se repararán. Con el tiempo se acumulan porque nadie sabe con certeza qué hacer con ellos.", "Desecharlos con la basura común puede ser peligroso, sobre todo cuando contienen baterías, y desaprovecha materiales y aparatos que aún podrían servir a otras personas. Al mismo tiempo, no siempre resulta claro si conviene reparar, cuánto costaría hacerlo o dónde llevarlos."], "desarrollar": ["Un inventario sencillo de aparatos en desuso que registre tipo, antigüedad, estado y posible destino, junto con un diagrama de decisión que ayude a elegir entre reparar, reutilizar, donar o llevar a un punto de acopio.", "El resultado puede ser una guía visual, una hoja de cálculo con criterios de decisión o una pequeña página web con preguntas que orienten a la persona hacia la mejor opción."], "ampliaciones": [{"titulo": "Reparar o reemplazar", "aporta": "construye una calculadora que compare el costo de reparar un aparato con el de comprar uno nuevo, considerando también su vida útil restante."}, {"titulo": "Duración de los aparatos", "aporta": "analiza cuánto tiempo se usan distintos tipos de dispositivos antes de dejarse de usar y por qué razones."}, {"titulo": "Mapa de opciones locales", "aporta": "reúne en un solo lugar los talleres, campañas de donación y puntos de acopio autorizados de tu zona."}], "objetivos": ["Identificar qué aparatos en desuso se acumulan en los hogares y por qué.", "Reconocer los riesgos y oportunidades de cada tipo de aparato.", "Diseñar un criterio claro para decidir qué hacer con cada uno.", "Representar ese criterio en un diagrama o herramienta fácil de usar.", "Comprobar si otras personas logran tomar una decisión sin ayuda al usar la guía."], "habilidades": ["Análisis de ciclo de vida de productos.", "Sostenibilidad y gestión de residuos.", "Electrónica básica.", "Diseño de árboles de decisión.", "Análisis de costos y beneficios.", "Comunicación clara de información."], "herramientas": ["Hoja de cálculo.", "Herramientas de diagramas de flujo.", "Mapas digitales para ubicar puntos de acopio.", "Herramientas web básicas si deseas crear una guía interactiva."], "lineamientos": ["No desarmes aparatos con baterías hinchadas, dañadas o conectados a la corriente, y no manipules baterías de litio deterioradas. Usa únicamente puntos de acopio y talleres autorizados, y recomienda siempre borrar la información personal de un dispositivo antes de donarlo o entregarlo.", "Evita inventar cifras ambientales o de ahorro: si presentas estimaciones, indica de dónde provienen y que son aproximadas."], "otroSector": "La misma metodología puede aplicarse a la gestión de equipos en oficinas, colegios, laboratorios, talleres o pequeñas empresas, y a otros tipos de residuos domésticos o comerciales."}$fd089ba$::jsonb,2),
('como-usas-el-agua-en-casa-sin-darte-cuenta','ambiente','{}'::text[],'¿Cómo usas el agua en casa sin darte cuenta?','Investiga cómo registrar y analizar hábitos relacionados con el uso del agua para comprender mejor cómo se distribuye el consumo dentro de un hogar e identificar oportunidades de ahorro basadas en datos.','Análisis','1 a 2 meses',39,array['Datos','Sostenibilidad','Hogar']::text[],array['investigar','resolver']::text[],'propios',null,'ingenieria ambiental ingenieria industrial ingenieria de sistemas estadistica economia administracion arquitectura ciencia de datos recoleccion de datos. diseno de metricas. analisis estadistico basico. visualizacion de informacion. interpretacion de tendencias. comunicacion de resultados. hoja de calculo. formularios digitales. aplicaciones de seguimiento y registro. herramientas de visualizacion de datos.',$f90b4b4${"id": "como-usas-el-agua-en-casa-sin-darte-cuenta", "area": "ambiente", "areas2": [], "titulo": "¿Cómo usas el agua en casa sin darte cuenta?", "resumen": "Investiga cómo registrar y analizar hábitos relacionados con el uso del agua para comprender mejor cómo se distribuye el consumo dentro de un hogar e identificar oportunidades de ahorro basadas en datos.", "tipo": "Análisis", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Datos", "Sostenibilidad", "Hogar"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "propios: puedes utilizar registros realizados por ti mismo o información disponible en recibos de consumo doméstico.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Ingeniería de Sistemas", "Estadística", "Economía", "Administración", "Arquitectura", "Ciencia de Datos"], "problema": ["El agua forma parte de casi todas las actividades diarias: cocinar, limpiar, ducharse, lavar ropa o regar plantas. Sin embargo, la mayoría de las personas solo observa el consumo cuando recibe una factura o cuando aparece una situación de escasez.", "Aunque muchas veces existe la intención de ahorrar agua, resulta difícil saber qué actividades generan el mayor consumo o qué cambios tendrían un impacto significativo. Sin información concreta, las decisiones suelen basarse en percepciones que no siempre reflejan la realidad.", "Comprender cómo se utiliza el agua permite identificar patrones, detectar desperdicios y evaluar hábitos que podrían optimizarse sin afectar la calidad de vida."], "desarrollar": ["Diseña una metodología sencilla para registrar actividades relacionadas con el consumo de agua durante varias semanas.", "Por ejemplo, podrías analizar:", {"lista": ["Frecuencia de uso de determinados servicios.", "Horarios de mayor consumo.", "Actividades que demandan más agua.", "Variaciones entre días de semana y fines de semana.", "Cambios producidos por nuevas prácticas de ahorro."]}, "A partir de la información recopilada, construye gráficos y visualizaciones que permitan comprender mejor los patrones observados."], "objetivos": ["Diseñar un sistema simple para registrar información relevante.", "Identificar actividades que concentran gran parte del consumo.", "Analizar tendencias a lo largo del tiempo.", "Visualizar resultados mediante tablas e indicadores comprensibles.", "Elaborar recomendaciones fundamentadas en la información obtenida."], "habilidades": ["Recolección de datos.", "Diseño de métricas.", "Análisis estadístico básico.", "Visualización de información.", "Interpretación de tendencias.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Aplicaciones de seguimiento y registro.", "Herramientas de visualización de datos."], "lineamientos": ["Documenta claramente cómo se registran los datos para mantener la consistencia durante todo el proyecto. Cuando no sea posible medir valores exactos, utiliza estimaciones razonables e indica los criterios utilizados.", "El objetivo principal es identificar patrones y oportunidades de mejora, no obtener mediciones técnicas de alta precisión.", "Si utilizas recibos de consumo, céntrate en los datos relevantes para el análisis y evita compartir información privada innecesaria."], "otroSector": "La misma metodología puede aplicarse al análisis del consumo eléctrico, combustible, materiales de oficina, recursos de producción o hábitos de utilización de servicios digitales."}$f90b4b4$::jsonb,3),
('papel-facultad','ambiente','{}'::text[],'¿Cuánto papel se desperdicia en tu centro de estudios?','Descubre cuánto papel se consume en un espacio real y qué formas concretas habría de reducirlo.','Análisis','~10 h',10,array['Medición','Reducción de residuos']::text[],array['investigar','resolver']::text[],'propios',null,'ingenieria ambiental ingenieria industrial quimica biologia administracion educacion diseno de una medicion graficos simples comunicacion de resultados hoja de calculo fichas de registro en papel o en linea',$f752301${"id": "papel-facultad", "area": "ambiente", "areas2": [], "titulo": "¿Cuánto papel se desperdicia en tu centro de estudios?", "resumen": "Descubre cuánto papel se consume en un espacio real y qué formas concretas habría de reducirlo.", "tipo": "Análisis", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Medición", "Reducción de residuos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Química", "Biología", "Administración", "Educación"], "problema": ["Se imprime mucho papel que termina sin usarse, pero casi nadie sabe cuánto ni dónde ocurre, así que es difícil cambiar los hábitos."], "desarrollar": ["Una medición sencilla durante unos días y una propuesta de dos o tres cambios para reducir el desperdicio."], "ampliaciones": [{"titulo": "Comparar espacios", "aporta": "Contrasta cuánto papel se usa en aulas, oficinas y laboratorios, y por qué cambia."}, {"titulo": "Traducirlo a impacto", "aporta": "Convierte las hojas en algo que se entienda a simple vista: dinero, árboles o tiempo de impresión."}, {"titulo": "Cambiar hábitos", "aporta": "Diseña una campaña breve para reducir el papel y descubre cómo la recibirían tus compañeros."}], "objetivos": ["Definir qué se va a medir y en qué lugar.", "Recoger datos durante una semana.", "Proponer cambios y estimar cuánto papel se ahorraría."], "habilidades": ["Diseño de una medición", "Gráficos simples", "Comunicación de resultados"], "herramientas": ["Hoja de cálculo", "Fichas de registro en papel o en línea"], "lineamientos": ["Avisa y pide permiso en el lugar donde midas.", "Registra cantidades, no personas.", "Presenta resultados sin culpar a nadie."], "otroSector": "La misma medición funciona con energía, agua o comida en un colegio, un restaurante o una oficina."}$f752301$::jsonb,4),
('lo-que-no-dice-la-oferta-de-practicas-cuanto-cuesta-realmente-ha','negocios',array['educacion']::text[],'Lo que no dice la oferta de prácticas: ¿cuánto cuesta realmente hacerlas?','Explora cómo calcular el costo total de realizar prácticas preprofesionales más allá del sueldo o la subvención: transporte, alimentación, tiempo de traslado, ropa, materiales y otros gastos que muchas veces nadie considera al aceptar una oferta.','Análisis','~12 h',12,array['Datos','Economía personal','Movilidad']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios',null,'economia estadistica ingenieria industrial ingenieria de sistemas administracion contabilidad ciencia de datos ingenieria civil analisis de costos. modelado en hoja de calculo. visualizacion de datos. pensamiento critico para la toma de decisiones. planificacion financiera basica. hoja de calculo. herramientas de graficos y visualizacion. mapas y planificadores de rutas, para estimar tiempos de traslado. herramientas web basicas si deseas crear una calculadora en linea.',$f8d3aca${"id": "lo-que-no-dice-la-oferta-de-practicas-cuanto-cuesta-realmente-ha", "area": "negocios", "areas2": ["educacion"], "titulo": "Lo que no dice la oferta de prácticas: ¿cuánto cuesta realmente hacerlas?", "resumen": "Explora cómo calcular el costo total de realizar prácticas preprofesionales más allá del sueldo o la subvención: transporte, alimentación, tiempo de traslado, ropa, materiales y otros gastos que muchas veces nadie considera al aceptar una oferta.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Datos", "Economía personal", "Movilidad"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "estimados: puedes usar estimaciones propias, promedios aproximados o un caso inventado, sin necesidad de compartir tus finanzas reales.", "carreras": ["Economía", "Estadística", "Ingeniería Industrial", "Ingeniería de Sistemas", "Administración", "Contabilidad", "Ciencia de Datos", "Ingeniería Civil"], "problema": ["Al recibir una oferta de prácticas, la comparación suele limitarse a una cifra: lo que pagan. Sin embargo, dos ofertas con el mismo monto pueden ser muy distintas cuando se suman los pasajes, el almuerzo diario, las horas perdidas en traslados y el impacto en el tiempo para estudiar.", "Esto afecta especialmente a quienes empiezan, porque aún no tienen referencia de cuánto cuesta trabajar fuera de casa todos los días. Algunas personas descubren tarde que una oferta aparentemente buena les deja casi nada, o que el tiempo de viaje les quita horas que necesitaban para sus cursos."], "desarrollar": ["Una calculadora o modelo sencillo que permita ingresar los datos de una oferta y obtener el costo mensual real, el pago neto aproximado y las horas semanales dedicadas a traslados.", "El resultado puede ser una hoja de cálculo con fórmulas claras, un panel comparativo o una pequeña aplicación web que permita comparar dos o más ofertas lado a lado."], "ampliaciones": [{"titulo": "Comparar rutas y horarios", "aporta": "analiza cómo cambia el costo y el tiempo de traslado según el medio de transporte o la hora de salida."}, {"titulo": "Incluir el costo de oportunidad", "aporta": "estima qué ocurre con tus horas de estudio o descanso según cada oferta."}, {"titulo": "Escenarios", "aporta": "simula qué pasaría si cambia el costo del transporte, el modelo de trabajo presencial o remoto, o la duración de las prácticas."}], "objetivos": ["Identificar todos los costos directos e indirectos asociados a unas prácticas.", "Diseñar un modelo claro para calcular el costo mensual real.", "Comparar varias ofertas con los mismos criterios.", "Representar los resultados de forma visual y fácil de interpretar.", "Reflexionar sobre qué factores, además del dinero, conviene considerar al elegir."], "habilidades": ["Análisis de costos.", "Modelado en hoja de cálculo.", "Visualización de datos.", "Pensamiento crítico para la toma de decisiones.", "Planificación financiera básica."], "herramientas": ["Hoja de cálculo.", "Herramientas de gráficos y visualización.", "Mapas y planificadores de rutas, para estimar tiempos de traslado.", "Herramientas web básicas si deseas crear una calculadora en línea."], "lineamientos": ["Utiliza cifras estimadas o ejemplos inventados en el material que compartas, y evita publicar tus ingresos o los de otras personas. Aclara que los resultados son aproximados y que cada situación personal puede ser distinta.", "El proyecto sirve para apoyar una decisión, no para decirle a nadie qué oferta aceptar: el aprendizaje, el entorno laboral y las oportunidades también cuentan aunque no se puedan medir en soles."], "otroSector": "La misma metodología puede aplicarse a comparar ofertas de empleo, decidir dónde vivir para estudiar o trabajar, evaluar el costo real de un emprendimiento pequeño o planificar el presupuesto de un proyecto de voluntariado."}$f8d3aca$::jsonb,0),
('como-dividir-gastos-compartidos-sin-pelearse','negocios',array['tecnologia']::text[],'¿Cómo dividir gastos compartidos sin pelearse?','Descubre cómo repartir gastos entre varias personas de forma justa y transparente, incluso cuando no todos consumen lo mismo ni pagan al mismo tiempo, y cómo reducir al mínimo la cantidad de transferencias necesarias para quedar a mano.','Prototipo','~20 h',20,array['Algoritmos','Matemática','Convivencia']::text[],array['crear','resolver','otro-sector']::text[],'ficticios',null,'ingenieria de sistemas matematica ciencias de la computacion economia estadistica administracion contabilidad psicologia logica y razonamiento matematico. diseno de algoritmos sencillos. modelado de datos. experiencia de usuario. comunicacion clara de resultados. hoja de calculo. lenguajes de programacion basicos. herramientas web sencillas. bases de datos simples si deseas guardar el historial.',$f8b4686${"id": "como-dividir-gastos-compartidos-sin-pelearse", "area": "negocios", "areas2": ["tecnologia"], "titulo": "¿Cómo dividir gastos compartidos sin pelearse?", "resumen": "Descubre cómo repartir gastos entre varias personas de forma justa y transparente, incluso cuando no todos consumen lo mismo ni pagan al mismo tiempo, y cómo reducir al mínimo la cantidad de transferencias necesarias para quedar a mano.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Algoritmos", "Matemática", "Convivencia"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: puedes inventar grupos de amigos, un viaje o un departamento compartido, sin usar gastos reales de nadie.", "carreras": ["Ingeniería de Sistemas", "Matemática", "Ciencias de la Computación", "Economía", "Estadística", "Administración", "Contabilidad", "Psicología"], "problema": ["En viajes, salidas, departamentos compartidos o proyectos grupales, una persona paga la cuenta, otra compra los insumos y una tercera adelanta el pasaje. Con el tiempo nadie recuerda exactamente quién debe a quién ni cuánto, y los pequeños desajustes terminan generando incomodidad o conflictos.", "El problema no es solo hacer las cuentas, sino hacerlo de una forma que todas las personas consideren razonable: no es lo mismo dividir en partes iguales que dividir según lo que cada uno consumió o según una regla acordada."], "desarrollar": ["Una herramienta sencilla en la que se puedan registrar personas, gastos, quién pagó y entre quiénes se reparte, y que calcule automáticamente cuánto debe cada persona y a quién.", "El resultado puede ser una hoja de cálculo con fórmulas, un pequeño programa o una aplicación web básica que muestre un resumen claro de las deudas pendientes."], "ampliaciones": [{"titulo": "Más allá de partes iguales", "aporta": "explora repartos justos cuando unos consumen más que otros o aportan distinto."}, {"titulo": "Otras monedas", "aporta": "adapta la herramienta para repartir tareas o tiempo, no solo dinero, en una casa compartida."}, {"titulo": "Desde el celular", "aporta": "convierte la hoja en una página simple que cualquier grupo pueda abrir y compartir."}], "objetivos": ["Identificar los distintos tipos de reparto que aparecen en situaciones reales.", "Diseñar una forma clara de registrar gastos y participantes.", "Calcular los saldos individuales de cada persona.", "Reducir la cantidad de transferencias necesarias para saldar las cuentas.", "Comprobar que los resultados sean fáciles de entender y verificar por todos."], "habilidades": ["Lógica y razonamiento matemático.", "Diseño de algoritmos sencillos.", "Modelado de datos.", "Experiencia de usuario.", "Comunicación clara de resultados."], "herramientas": ["Hoja de cálculo.", "Lenguajes de programación básicos.", "Herramientas web sencillas.", "Bases de datos simples si deseas guardar el historial."], "lineamientos": ["Prueba la herramienta con datos inventados antes de usarla con dinero real. Si la utilizas con amistades o compañeros de vivienda, asegúrate de que todos estén de acuerdo con las reglas de reparto y puedan revisar los cálculos.", "Evita guardar datos bancarios o información financiera personal: el proyecto solo necesita nombres, montos y reglas de reparto."], "otroSector": "La misma idea puede aplicarse a la contabilidad de asociaciones estudiantiles, la gestión de cuotas de un grupo, el reparto de costos en proyectos colaborativos o la liquidación de gastos en equipos de trabajo."}$f8b4686$::jsonb,1),
('un-sistema-para-organizar-las-entregas-de-un-negocio-pequeno','negocios',array['tecnologia']::text[],'Un sistema para organizar las entregas de un negocio pequeño','Descubre cómo organizar pedidos, clientes, rutas y horarios de reparto para ayudar a un pequeño negocio a gestionar sus entregas de manera más eficiente.','Prototipo','~35 h',35,array['Logística','Organización']::text[],array['crear','resolver','otro-sector']::text[],'ficticios',null,'ingenieria de sistemas ingenieria industrial administracion ingenieria de transporte logistica ciencia de datos emprendimiento diseno de sistemas. gestion de informacion. modelado de procesos. diseno de interfaces. organizacion logistica. resolucion de problemas. hoja de calculo. formularios digitales. bases de datos. herramientas de diagramacion. tecnologias web si deseas desarrollar una aplicacion.',$fd7697d${"id": "un-sistema-para-organizar-las-entregas-de-un-negocio-pequeno", "area": "negocios", "areas2": ["tecnologia"], "titulo": "Un sistema para organizar las entregas de un negocio pequeño", "resumen": "Descubre cómo organizar pedidos, clientes, rutas y horarios de reparto para ayudar a un pequeño negocio a gestionar sus entregas de manera más eficiente.", "tipo": "Prototipo", "tiempo": "~35 h", "horas": 35, "etiquetas": ["Logística", "Organización"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: puedes construirlo utilizando pedidos simulados sin necesidad de trabajar con un negocio real.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Administración", "Ingeniería de Transporte", "Logística", "Ciencia de Datos", "Emprendimiento"], "problema": ["Muchos pequeños negocios comienzan gestionando sus pedidos mediante llamadas, mensajes o listas escritas a mano. Mientras el volumen de ventas es reducido, este sistema suele funcionar. Sin embargo, a medida que aumentan los pedidos, aparecen nuevos desafíos: entregas olvidadas, direcciones equivocadas, retrasos, duplicación de información y dificultades para conocer el estado de cada pedido.", "En muchos casos, el problema no es la falta de esfuerzo, sino la ausencia de herramientas que permitan visualizar y organizar toda la información de forma clara.", "La logística no solo afecta al negocio. También influye en la experiencia del cliente, que espera recibir información precisa sobre cuándo llegará su pedido y cuál es su estado actual."], "desarrollar": ["Diseña un sistema que permita registrar pedidos, clientes y estados de entrega.", "Como mínimo, el prototipo puede incluir:", {"lista": ["Registro de pedidos.", "Datos básicos del cliente.", "Estado de la entrega.", "Fecha prevista.", "Historial de pedidos."]}, "Puede construirse mediante una hoja de cálculo avanzada, una base de datos sencilla o una aplicación web básica."], "ampliaciones": [{"titulo": "Planificación de rutas", "aporta": "explora cómo agrupar entregas cercanas para reducir tiempos de desplazamiento."}, {"titulo": "Seguimiento de pedidos", "aporta": "imagina una forma de mostrar al cliente el avance de su entrega."}, {"titulo": "Análisis del negocio", "aporta": "descubre qué zonas reciben más pedidos y en qué horarios existe mayor demanda."}], "objetivos": ["Comprender el flujo completo de una entrega.", "Diseñar una estructura de información para registrar pedidos.", "Organizar estados y etapas del proceso.", "Construir un prototipo funcional.", "Identificar oportunidades para reducir errores y tiempos de gestión."], "habilidades": ["Diseño de sistemas.", "Gestión de información.", "Modelado de procesos.", "Diseño de interfaces.", "Organización logística.", "Resolución de problemas."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Bases de datos.", "Herramientas de diagramación.", "Tecnologías web si deseas desarrollar una aplicación."], "lineamientos": ["Puedes utilizar un negocio ficticio o inspirarte en un emprendimiento real. Si utilizas información de un negocio existente, evita recopilar datos sensibles o privados.", "Comienza registrando pocos pedidos y aumenta la complejidad progresivamente. Prioriza que el sistema sea fácil de utilizar antes de añadir funciones avanzadas."], "otroSector": "La misma lógica puede utilizarse para gestionar préstamos de equipos, distribución de materiales educativos, entregas de medicamentos, préstamos bibliotecarios o cualquier actividad que implique seguimiento de recursos."}$fd7697d$::jsonb,2),
('por-que-un-negocio-pequeno-pierde-clientes','negocios','{}'::text[],'¿Por qué un negocio pequeño pierde clientes?','Descubre cómo descubrir por qué un negocio pequeño, como una bodega, una cafetería o un taller, vende menos que antes, y cómo convertir esa sospecha en un análisis ordenado con datos.','Análisis','4 a 8 semanas',36,array['Datos','Negocios','Clientes']::text[],array['investigar','resolver']::text[],'ficticios',null,'economia administracion marketing estadistica ingenieria industrial ingenieria de sistemas ciencia de datos contabilidad analisis y visualizacion de datos. formulacion y prueba de hipotesis. conceptos basicos de negocios y de atencion al cliente. estadistica descriptiva. comunicacion de resultados. hoja de calculo. herramientas de graficos y visualizacion. formularios digitales para encuestas breves. herramientas de programacion o de analisis de datos si deseas ampliar el proyecto.',$f83cf0b${"id": "por-que-un-negocio-pequeno-pierde-clientes", "area": "negocios", "areas2": [], "titulo": "¿Por qué un negocio pequeño pierde clientes?", "resumen": "Descubre cómo descubrir por qué un negocio pequeño, como una bodega, una cafetería o un taller, vende menos que antes, y cómo convertir esa sospecha en un análisis ordenado con datos.", "tipo": "Análisis", "tiempo": "4 a 8 semanas", "horas": 36, "etiquetas": ["Datos", "Negocios", "Clientes"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios o con permiso: puedes simular ventas, encuestas y comentarios de un negocio imaginario, o trabajar con uno real solo si su dueño lo autoriza y se protege la identidad de sus clientes.", "carreras": ["Economía", "Administración", "Marketing", "Estadística", "Ingeniería Industrial", "Ingeniería de Sistemas", "Ciencia de Datos", "Contabilidad"], "problema": ["Muchos negocios pequeños notan que las ventas bajan, pero no saben por qué. Las explicaciones suelen ser intuiciones: \"hay más competencia\", \"la gente ya no compra como antes\" o \"es por el precio\". Sin registros ordenados, es difícil saber si realmente lo es.", "Las causas pueden ser muy distintas: un cambio de horarios, una mala experiencia de atención, un producto que dejó de estar disponible, una competencia nueva o simplemente que los clientes frecuentes se fueron alejando poco a poco sin que nadie lo notara."], "desarrollar": ["Construye un registro sencillo de ventas por día, por tipo de producto y por tipo de cliente, y formula tres o cuatro hipótesis sobre posibles causas de la caída.", "Analiza los datos para ver cuáles hipótesis se sostienen y cuáles no, y propone dos o tres acciones concretas y medibles, como cambiar un horario, ajustar una oferta o mejorar la atención.", "El resultado puede ser un panel comparativo, un informe con gráficos o una hoja de cálculo con el análisis y las recomendaciones."], "ampliaciones": [{"titulo": "Segmentar clientes", "aporta": "separa a los clientes frecuentes, ocasionales y los que dejaron de venir, y analiza en qué se diferencian."}, {"titulo": "Medir retención", "aporta": "calcula qué proporción de clientes vuelve en las semanas siguientes a su primera compra."}, {"titulo": "Simular una promoción", "aporta": "estima qué efecto podría tener una oferta y cómo comprobar si funcionó o fue solo casualidad."}], "objetivos": ["Diseñar un registro simple de ventas y clientes.", "Formular hipótesis razonables sobre la caída de ventas.", "Analizar los datos para evaluar cada hipótesis.", "Distinguir entre una coincidencia y una causa probable.", "Proponer acciones concretas y una forma de medir su resultado."], "habilidades": ["Análisis y visualización de datos.", "Formulación y prueba de hipótesis.", "Conceptos básicos de negocios y de atención al cliente.", "Estadística descriptiva.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Herramientas de gráficos y visualización.", "Formularios digitales para encuestas breves.", "Herramientas de programación o de análisis de datos si deseas ampliar el proyecto."], "lineamientos": ["Si trabajas con un negocio real, pide permiso a su dueño, anonimiza la información y evita recopilar datos personales de clientes sin su consentimiento. No compartas cifras de ventas reales sin autorización.", "Recuerda que encontrar una relación entre dos datos no demuestra que uno cause el otro, y evita prometer resultados: presenta las recomendaciones como propuestas que deben probarse."], "otroSector": "La misma metodología puede aplicarse a academias, gimnasios, servicios por suscripción, asociaciones, clubes o cualquier organización que necesite entender por qué las personas dejan de participar."}$f83cf0b$::jsonb,3),
('un-asistente-que-compara-precios-por-ti','negocios',array['tecnologia']::text[],'Un asistente que compara precios por ti','Investiga cómo reunir y comparar información de distintos productos para ayudar a las personas a tomar decisiones de compra mejor informadas.','Prototipo','1 a 2 meses',39,array['Consumo','Comparación de datos']::text[],array['crear','resolver','otro-sector']::text[],'publicos',null,'ingenieria de sistemas administracion economia estadistica ingenieria industrial marketing ciencia de datos organizacion de informacion. diseno de bases de datos. visualizacion de datos. experiencia de usuario. pensamiento analitico. evaluacion de criterios. hoja de calculo. formularios digitales. bases de datos sencillas. herramientas web. software de visualizacion.',$f285907${"id": "un-asistente-que-compara-precios-por-ti", "area": "negocios", "areas2": ["tecnologia"], "titulo": "Un asistente que compara precios por ti", "resumen": "Investiga cómo reunir y comparar información de distintos productos para ayudar a las personas a tomar decisiones de compra mejor informadas.", "tipo": "Prototipo", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Consumo", "Comparación de datos"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: pueden obtenerse de catálogos en línea, folletos comerciales, publicaciones de tiendas o ejemplos simulados.", "carreras": ["Ingeniería de Sistemas", "Administración", "Economía", "Estadística", "Ingeniería Industrial", "Marketing", "Ciencia de Datos"], "problema": ["Cuando una persona quiere comprar un producto, normalmente debe revisar varias páginas web, aplicaciones, publicaciones o establecimientos para encontrar la mejor opción. Este proceso puede consumir bastante tiempo, especialmente cuando existen múltiples modelos, marcas y características que comparar.", "Muchas veces las decisiones terminan tomándose únicamente por precio o por publicidad, sin contar con una visión completa de otros factores importantes como características, disponibilidad, costos adicionales o relación calidad-precio.", "Además, cuando la información está dispersa, resulta difícil identificar patrones o entender cuál alternativa ofrece realmente más valor."], "desarrollar": ["Diseña un sistema que permita registrar productos y comparar sus características principales en un solo lugar.", "El prototipo puede incluir:", {"lista": ["Nombre del producto.", "Precio.", "Marca.", "Características principales.", "Fecha de consulta.", "Observaciones adicionales."]}, "La información puede visualizarse mediante tablas, filtros o paneles comparativos que faciliten la toma de decisiones."], "objetivos": ["Identificar qué información resulta útil para comparar productos.", "Diseñar una estructura clara para organizar datos de distintas fuentes.", "Construir una herramienta que facilite la comparación.", "Visualizar diferencias entre alternativas.", "Evaluar qué criterios influyen más en una decisión de compra."], "habilidades": ["Organización de información.", "Diseño de bases de datos.", "Visualización de datos.", "Experiencia de usuario.", "Pensamiento analítico.", "Evaluación de criterios."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Bases de datos sencillas.", "Herramientas web.", "Software de visualización."], "lineamientos": ["Utiliza información verificable y documenta siempre de dónde provienen los datos. Si los precios cambian con frecuencia, indica la fecha de consulta de cada registro.", "El objetivo del proyecto no es recomendar una compra específica, sino facilitar el análisis y comparación de alternativas."], "otroSector": "La misma metodología puede aplicarse a la comparación de proveedores, servicios de internet, planes educativos, equipos tecnológicos, materiales de construcción o alternativas energéticas."}$f285907$::jsonb,4),
('como-organizar-un-evento-grande-sin-que-se-caiga-nada','negocios',array['sociedad']::text[],'¿Cómo organizar un evento grande sin que se caiga nada?','Imagina cómo planificar un evento con mucha gente, como una feria, una semana académica o una competencia, para anticipar qué puede salir mal, repartir responsabilidades y tener un plan B antes de que ocurra un imprevisto.','Plan','1 a 2 meses',39,array['Planificación','Gestión de proyectos','Trabajo en equipo']::text[],array['resolver','crear','otro-sector']::text[],'ficticios',null,'administracion ingenieria industrial ingenieria de sistemas comunicaciones psicologia ingenieria civil marketing educacion planificacion y gestion de proyectos. gestion de riesgos. comunicacion y coordinacion de equipos. organizacion del tiempo y de los recursos. liderazgo y toma de decisiones. hoja de calculo. tableros de tareas. calendarios compartidos. herramientas de diagramas y cronogramas. herramientas web sencillas si deseas crear un panel de seguimiento.',$fb1b0de${"id": "como-organizar-un-evento-grande-sin-que-se-caiga-nada", "area": "negocios", "areas2": ["sociedad"], "titulo": "¿Cómo organizar un evento grande sin que se caiga nada?", "resumen": "Imagina cómo planificar un evento con mucha gente, como una feria, una semana académica o una competencia, para anticipar qué puede salir mal, repartir responsabilidades y tener un plan B antes de que ocurra un imprevisto.", "tipo": "Plan", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Planificación", "Gestión de proyectos", "Trabajo en equipo"], "intencion": ["resolver", "crear", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: puedes planificar un evento imaginario, o uno real y pequeño que ya estés organizando, siempre con información que puedas compartir.", "carreras": ["Administración", "Ingeniería Industrial", "Ingeniería de Sistemas", "Comunicaciones", "Psicología", "Ingeniería Civil", "Marketing", "Educación"], "problema": ["Cuando se organiza un evento grande, muchas tareas dependen unas de otras: el local, los permisos, la difusión, los invitados, el sonido, la logística y los voluntarios. Si una falla, el efecto puede extenderse al resto, y a menudo se descubre demasiado tarde que nadie sabía quién era responsable de qué.", "En muchos eventos estudiantiles el plan vive solo en la cabeza de una o dos personas, en chats extensos o en listas sueltas. Cuando alguien se enferma, cambia el horario o falla un proveedor, el equipo improvisa en lugar de reaccionar con un plan."], "desarrollar": ["Un plan de organización para un evento concreto que incluya un cronograma con tareas y responsables, una lista de riesgos con su plan de respuesta y una forma sencilla de seguir el avance.", "El resultado puede ser un tablero de tareas, una hoja de cálculo con fechas y estados, o una pequeña aplicación de seguimiento."], "ampliaciones": [{"titulo": "Dependencias entre tareas", "aporta": "identifica qué tareas retrasan a otras y cuál es la ruta que define la duración total del plan."}, {"titulo": "Control de aforo y flujo de personas", "aporta": "estima cuántas personas caben, cómo se moverán y dónde se formarían filas."}, {"titulo": "Presupuesto y escenarios", "aporta": "analiza qué pasa con los costos si la asistencia es mayor o menor de lo esperado."}], "objetivos": ["Identificar las tareas, responsables y fechas clave de un evento.", "Reconocer los riesgos más probables y su impacto.", "Diseñar planes de respuesta para los imprevistos más importantes.", "Establecer una forma clara de comunicar avances y cambios al equipo.", "Evaluar el plan con otras personas y mejorarlo con sus observaciones."], "habilidades": ["Planificación y gestión de proyectos.", "Gestión de riesgos.", "Comunicación y coordinación de equipos.", "Organización del tiempo y de los recursos.", "Liderazgo y toma de decisiones."], "herramientas": ["Hoja de cálculo.", "Tableros de tareas.", "Calendarios compartidos.", "Herramientas de diagramas y cronogramas.", "Herramientas web sencillas si deseas crear un panel de seguimiento."], "lineamientos": ["Si el evento es real, verifica los permisos, las normas de seguridad y el aforo permitido con las personas o entidades responsables, y no asumas que tu plan reemplaza esas validaciones. Evita incluir datos personales de asistentes o voluntarios en el material que compartas.", "Pide opiniones a quienes ya organizaron eventos similares: su experiencia suele revelar riesgos que el papel no muestra."], "otroSector": "La misma metodología puede aplicarse a lanzamientos de productos, ferias comerciales, congresos académicos, campañas de voluntariado, celebraciones familiares grandes o la planificación de una obra o proyecto de ingeniería."}$fb1b0de$::jsonb,5),
('un-catalogo-digital-para-emprendedores-de-tu-zona','negocios',array['tecnologia','sociedad']::text[],'Un catálogo digital para emprendedores de tu zona','Explora cómo reunir en un solo lugar información sobre productos, servicios y emprendimientos de una comunidad para facilitar que más personas puedan descubrirlos, compararlos y contactarlos.','Prototipo','2 a 4 meses',78,array['Emprendimiento','Comunidad','Comercio digital']::text[],array['crear','resolver','otro-sector']::text[],'publicos',null,'ingenieria de sistemas administracion marketing comunicaciones diseno ux economia ciencia de datos emprendimiento diseno de sistemas de informacion. organizacion de contenidos. diseno de interfaces. experiencia de usuario. gestion de bases de datos. comunicacion digital. hojas de calculo. bases de datos sencillas. formularios digitales. herramientas web. sistemas de diseno para prototipos.',$fcc5794${"id": "un-catalogo-digital-para-emprendedores-de-tu-zona", "area": "negocios", "areas2": ["tecnologia", "sociedad"], "titulo": "Un catálogo digital para emprendedores de tu zona", "resumen": "Explora cómo reunir en un solo lugar información sobre productos, servicios y emprendimientos de una comunidad para facilitar que más personas puedan descubrirlos, compararlos y contactarlos.", "tipo": "Prototipo", "tiempo": "2 a 4 meses", "horas": 78, "etiquetas": ["Emprendimiento", "Comunidad", "Comercio digital"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos, propios o proporcionados por los emprendedores participantes.", "carreras": ["Ingeniería de Sistemas", "Administración", "Marketing", "Comunicaciones", "Diseño UX", "Economía", "Ciencia de Datos", "Emprendimiento"], "problema": ["Muchos pequeños emprendedores ofrecen productos o servicios de calidad, pero tienen dificultades para llegar a nuevos clientes. En muchos casos, la información se encuentra dispersa entre redes sociales, grupos de mensajería, publicaciones temporales o recomendaciones boca a boca.", "Como resultado, potenciales clientes no saben que esos negocios existen o tienen dificultades para encontrarlos cuando los necesitan. Al mismo tiempo, los emprendedores deben invertir una gran cantidad de tiempo repitiendo información sobre sus productos, horarios, métodos de contacto o ubicaciones.", "La falta de visibilidad puede limitar el crecimiento de iniciativas que sí generan valor para la comunidad."], "desarrollar": ["Diseña un catálogo digital que permita reunir información básica sobre distintos emprendimientos.", "El sistema puede incluir:", {"lista": ["Nombre del emprendimiento.", "Descripción de productos o servicios.", "Categoría.", "Datos de contacto.", "Ubicación.", "Horarios de atención.", "Imágenes de referencia."]}, "La información puede mostrarse mediante fichas, categorías, filtros o un buscador sencillo."], "objetivos": ["Identificar qué información necesitan los usuarios para descubrir un emprendimiento.", "Diseñar una estructura clara para organizar negocios y servicios.", "Crear una plataforma fácil de consultar.", "Facilitar la búsqueda mediante categorías y filtros.", "Evaluar cómo una mejor organización de la información puede aumentar la visibilidad de los negocios."], "habilidades": ["Diseño de sistemas de información.", "Organización de contenidos.", "Diseño de interfaces.", "Experiencia de usuario.", "Gestión de bases de datos.", "Comunicación digital."], "herramientas": ["Hojas de cálculo.", "Bases de datos sencillas.", "Formularios digitales.", "Herramientas web.", "Sistemas de diseño para prototipos."], "lineamientos": ["Solicita autorización antes de publicar información de negocios reales. Mantén actualizados los datos importantes y documenta cuándo se realizó la última verificación.", "Evita recopilar información innecesaria y prioriza datos que realmente ayuden a los usuarios a encontrar y comprender lo que ofrece cada emprendimiento.", "Si el catálogo crece, define criterios claros para clasificar los negocios y mantener la calidad de la información."], "otroSector": "La misma idea puede utilizarse para directorios de profesionales independientes, asociaciones culturales, organizaciones sociales, servicios comunitarios, proyectos estudiantiles o iniciativas de investigación."}$fcc5794$::jsonb,6),
('costos-negocio','negocios','{}'::text[],'¿Cuánto cuesta realmente un negocio pequeño?','Explora cómo calcular los costos reales de una bodega, un puesto o un servicio y descubre cuál sería su precio justo.','Análisis','~12 h',12,array['Costos','Emprendimiento']::text[],array['investigar','otro-sector']::text[],'propios',null,'economia administracion contabilidad ingenieria industrial ingenieria economica estadistica costeo basico hoja de calculo explicar numeros con palabras sencillas hoja de calculo entrevista breve con el dueno (opcional)',$f9b3ea3${"id": "costos-negocio", "area": "negocios", "areas2": [], "titulo": "¿Cuánto cuesta realmente un negocio pequeño?", "resumen": "Explora cómo calcular los costos reales de una bodega, un puesto o un servicio y descubre cuál sería su precio justo.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Costos", "Emprendimiento"], "intencion": ["investigar", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes", "carreras": ["Economía", "Administración", "Contabilidad", "Ingeniería Industrial", "Ingeniería Económica", "Estadística"], "problema": ["Muchos negocios pequeños fijan precios por intuición y no incluyen su tiempo, los desperdicios ni los gastos fijos, así que ganan menos de lo que creen."], "desarrollar": ["Una hoja de costos que separe lo fijo de lo variable, incluya el tiempo de trabajo y calcule un punto de equilibrio y un rango de precio."], "objetivos": ["Identificar todos los costos de un negocio concreto.", "Calcular cuánto hay que vender para no perder.", "Explicar el resultado en una página que entienda su dueño."], "habilidades": ["Costeo básico", "Hoja de cálculo", "Explicar números con palabras sencillas"], "herramientas": ["Hoja de cálculo", "Entrevista breve con el dueño (opcional)"], "lineamientos": ["Puedes usar un negocio ficticio con datos realistas.", "Si hablas con un dueño real, respeta lo que no quiera compartir.", "Deja a la vista los supuestos que hiciste."], "otroSector": "Sirve para un taller de reparaciones, un servicio de asesorías, un emprendimiento digital o una actividad de recaudación."}$f9b3ea3$::jsonb,7),
('esta-tu-casa-o-tu-salon-listo-para-un-sismo','ciudades',array['sociedad']::text[],'¿Está tu casa o tu salón listo para un sismo?','Imagina cómo identificar los riesgos de un espacio cotidiano frente a un sismo y cómo diseñar un plan sencillo para que las personas sepan qué hacer, adónde ir y qué tener a la mano.','Plan','~15 h',15,array['Gestión de riesgos','Seguridad']::text[],array['resolver','crear','otro-sector']::text[],'propios',null,'ingenieria civil ingenieria ambiental ingenieria industrial arquitectura ingenieria de sistemas comunicaciones educacion administracion identificacion y analisis de riesgos. diseno de planos y esquemas. comunicacion clara de informacion. planificacion de contingencias. empatia y pensamiento centrado en las personas. programas de dibujo o diseno sencillo. hoja de calculo para la lista de riesgos y suministros. herramientas de presentacion o edicion de afiches. herramientas web basicas si deseas crear una version digital.',$f56105f${"id": "esta-tu-casa-o-tu-salon-listo-para-un-sismo", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Está tu casa o tu salón listo para un sismo?", "resumen": "Imagina cómo identificar los riesgos de un espacio cotidiano frente a un sismo y cómo diseñar un plan sencillo para que las personas sepan qué hacer, adónde ir y qué tener a la mano.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Gestión de riesgos", "Seguridad"], "intencion": ["resolver", "crear", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes usar el plano de tu casa, de tu salón de clases o de un espacio inventado.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Ingeniería Industrial", "Arquitectura", "Ingeniería de Sistemas", "Comunicaciones", "Educación", "Administración"], "problema": ["En zonas con actividad sísmica, casi todas las personas saben que \"algún día\" puede temblar fuerte, pero pocas tienen un plan concreto. Los muebles altos sin sujetar, las rutas de salida bloqueadas o la falta de un punto de reunión conocido pueden convertir un evento manejable en una situación de riesgo.", "Además, la información suele estar dispersa: carteles que nadie lee, mensajes que se olvidan o indicaciones que cada persona entiende de forma distinta. En un momento de tensión, un plan complicado simplemente no se usa."], "desarrollar": ["Un plan básico para un espacio concreto que incluya un plano sencillo con zonas seguras, rutas de salida y puntos de reunión, una lista de elementos de riesgo detectados y una lista de suministros de emergencia.", "El resultado puede ser un documento visual, un afiche, una hoja de cálculo o una pequeña página web que cualquier persona pueda entender en menos de dos minutos."], "ampliaciones": [{"titulo": "Simular una evacuación", "aporta": "estima cuánto tardarían distintas personas en salir y qué cuellos de botella aparecerían en puertas o pasillos."}, {"titulo": "Medir si el plan funciona", "aporta": "realiza un simulacro con personas voluntarias y registra qué dudas o errores aparecen."}, {"titulo": "Adaptar el plan", "aporta": "explora cómo cambiaría para personas mayores, niños o personas con movilidad reducida."}], "objetivos": ["Identificar los riesgos físicos y de organización de un espacio frente a un sismo.", "Diseñar rutas de salida y puntos de reunión claros.", "Elaborar una lista de suministros básicos de emergencia.", "Comunicar el plan de forma simple y fácil de recordar.", "Comprobar si otras personas entienden el plan sin necesidad de explicación adicional."], "habilidades": ["Identificación y análisis de riesgos.", "Diseño de planos y esquemas.", "Comunicación clara de información.", "Planificación de contingencias.", "Empatía y pensamiento centrado en las personas."], "herramientas": ["Programas de dibujo o diseño sencillo.", "Hoja de cálculo para la lista de riesgos y suministros.", "Herramientas de presentación o edición de afiches.", "Herramientas web básicas si deseas crear una versión digital."], "lineamientos": ["Basa el plan en guías oficiales de defensa civil y gestión del riesgo de desastres, y no inventes recomendaciones técnicas. Este proyecto no reemplaza una evaluación estructural: si sospechas de problemas en una edificación, consulta a profesionales calificados.", "Si realizas un simulacro, hazlo con previo aviso, sin correr y sin poner a nadie en riesgo. Evita recopilar información personal innecesaria de las personas que participen."], "otroSector": "La misma metodología puede aplicarse a planes de emergencia de oficinas, colegios, talleres, locales comerciales, laboratorios o eventos con mucha asistencia, y a otros tipos de emergencia como incendios o cortes prolongados de servicios."}$f56105f$::jsonb,0),
('que-deja-de-funcionar-si-se-va-la-luz-o-el-internet','ciudades',array['tecnologia']::text[],'¿Qué deja de funcionar si se va la luz o el internet?','Investiga de qué depende realmente tu vida diaria de la electricidad y la conexión a internet, y cómo prepararte para seguir estudiando, trabajando y comunicándote cuando uno de los dos servicios falla durante varias horas.','Plan','~15 h',15,array['Gestión de riesgos','Continuidad','Energía']::text[],array['resolver','crear','otro-sector']::text[],'propios',null,'ingenieria electrica ingenieria electronica ingenieria de telecomunicaciones ingenieria industrial ingenieria de sistemas ingenieria ambiental administracion analisis de dependencias y riesgos. planificacion de contingencias. conceptos basicos de energia y comunicaciones. organizacion de informacion. comunicacion clara y breve. hoja de calculo. herramientas de diagramas. editor de documentos o presentaciones. aplicaciones de notas y almacenamiento con acceso sin conexion.',$fcbee90${"id": "que-deja-de-funcionar-si-se-va-la-luz-o-el-internet", "area": "ciudades", "areas2": ["tecnologia"], "titulo": "¿Qué deja de funcionar si se va la luz o el internet?", "resumen": "Investiga de qué depende realmente tu vida diaria de la electricidad y la conexión a internet, y cómo prepararte para seguir estudiando, trabajando y comunicándote cuando uno de los dos servicios falla durante varias horas.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Gestión de riesgos", "Continuidad", "Energía"], "intencion": ["resolver", "crear", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes analizar tu propia casa, un departamento compartido o un negocio pequeño inventado.", "carreras": ["Ingeniería Eléctrica", "Ingeniería Electrónica", "Ingeniería de Telecomunicaciones", "Ingeniería Industrial", "Ingeniería de Sistemas", "Ingeniería Ambiental", "Administración"], "problema": ["Un corte de luz o de internet parece un inconveniente menor hasta que coincide con una entrega, una clase virtual, un examen en línea o una llamada importante. En ese momento se descubre que muchas cosas dependían de esos servicios sin que nadie lo hubiera notado: la bomba de agua, el router, la carga del celular, las alarmas, los archivos que solo están en la nube o las conexiones de trabajo.", "Como estas interrupciones no suelen avisar con anticipación, la mayoría de las personas improvisa. Y cuando se improvisa bajo presión, se pierden tiempo, trabajo y a veces dinero."], "desarrollar": ["Un inventario de todo lo que depende de la luz y del internet en un espacio concreto, clasificado según qué tan crítico es y cuánto tiempo podría pasar sin funcionar.", "A partir de ese inventario, un plan para tres escenarios de duración, como unas 2 horas, una jornada y un día completo, con acciones concretas para cada uno.", "El resultado puede ser una tabla de dependencias, un diagrama o una guía de una página que cualquiera pueda consultar rápidamente."], "ampliaciones": [{"titulo": "Autonomía de energía", "aporta": "calcula cuánto tiempo podrían funcionar tus dispositivos con baterías externas y qué prioridades conviene proteger."}, {"titulo": "Trabajo sin conexión", "aporta": "explora cómo organizar tus archivos y tareas para poder avanzar aunque no haya internet."}, {"titulo": "Impacto en un negocio", "aporta": "estima cuánto costaría una interrupción de varias horas en un negocio pequeño y qué medidas reducirían ese costo."}], "objetivos": ["Identificar las dependencias de electricidad e internet en un espacio cotidiano.", "Clasificar esas dependencias según su importancia.", "Diseñar acciones preventivas y de respuesta para distintos tiempos de interrupción.", "Presentar el plan en un formato breve que se pueda usar en el momento.", "Comprobar si otra persona sabría qué hacer al leerlo, sin necesidad de explicaciones."], "habilidades": ["Análisis de dependencias y riesgos.", "Planificación de contingencias.", "Conceptos básicos de energía y comunicaciones.", "Organización de información.", "Comunicación clara y breve."], "herramientas": ["Hoja de cálculo.", "Herramientas de diagramas.", "Editor de documentos o presentaciones.", "Aplicaciones de notas y almacenamiento con acceso sin conexión."], "lineamientos": ["No manipules instalaciones eléctricas ni intentes soluciones improvisadas con la red de tu hogar: ante cualquier duda, consulta a un profesional. Si consideras generadores, velas o fuentes de calor, investiga primero sus riesgos de incendio e intoxicación, y nunca uses equipos de combustión en espacios cerrados.", "Si en el hogar hay personas que dependen de equipos eléctricos por razones de salud, ese plan debe elaborarse con orientación profesional y no solo con este ejercicio."], "otroSector": "La misma metodología puede aplicarse a planes de continuidad en colegios, laboratorios, talleres, consultorios, tiendas, oficinas o centros de datos, y a la preparación frente a otros eventos que interrumpen servicios básicos."}$fcbee90$::jsonb,1),
('por-donde-camina-realmente-tu-barrio','ciudades',array['sociedad']::text[],'¿Por dónde camina realmente tu barrio?','Explora cómo se desplazan las personas en una zona determinada para descubrir qué rutas se utilizan con mayor frecuencia, dónde se producen congestiones y qué oportunidades existen para mejorar la movilidad.','Investigación','1 a 2 meses',39,array['Movilidad','Datos','Comunidad']::text[],array['investigar','otro-sector']::text[],'publicos',null,'ingenieria de sistemas ingenieria civil ingenieria de transporte arquitectura urbanismo estadistica geografia administracion publica ciencia de datos observacion sistematica. analisis de datos. interpretacion de patrones. cartografia basica. visualizacion de informacion. investigacion aplicada. hojas de calculo. aplicaciones de mapas. herramientas de visualizacion de datos. formularios de registro. software de elaboracion de mapas.',$fade5a3${"id": "por-donde-camina-realmente-tu-barrio", "area": "ciudades", "areas2": ["sociedad"], "titulo": "¿Por dónde camina realmente tu barrio?", "resumen": "Explora cómo se desplazan las personas en una zona determinada para descubrir qué rutas se utilizan con mayor frecuencia, dónde se producen congestiones y qué oportunidades existen para mejorar la movilidad.", "tipo": "Investigación", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Movilidad", "Datos", "Comunidad"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "observaciones propias o públicos: puedes registrar tus propias observaciones o utilizar información abierta disponible en mapas, municipios o fuentes de transporte.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Civil", "Ingeniería de Transporte", "Arquitectura", "Urbanismo", "Estadística", "Geografía", "Administración Pública", "Ciencia de Datos"], "problema": ["Todos los días miles de personas se desplazan para estudiar, trabajar, realizar compras o acceder a servicios. Sin embargo, gran parte de las decisiones relacionadas con la movilidad se toman a partir de percepciones y no de observaciones sistemáticas.", "Una calle puede parecer muy transitada porque siempre la observamos en hora punta, mientras que otra podría concentrar la mayor parte de los desplazamientos del barrio sin que resulte evidente. Del mismo modo, algunos cruces, paraderos o rutas pueden generar retrasos frecuentes que pasan desapercibidos porque nadie recopila información sobre ellos.", "Comprender cómo se mueve una comunidad es el primer paso para detectar problemas y proponer mejoras fundamentadas."], "desarrollar": ["Selecciona una zona específica y registra durante varias semanas información relacionada con desplazamientos, flujo de personas o utilización de rutas.", "El proyecto puede incluir:", {"lista": ["Rutas más utilizadas.", "Horarios de mayor movimiento.", "Puntos de congestión.", "Lugares de cruce frecuente.", "Tiempos aproximados de recorrido."]}, "Utiliza los datos recogidos para construir mapas, gráficos o visualizaciones que permitan identificar patrones de movilidad."], "objetivos": ["Diseñar una estrategia para observar y registrar desplazamientos.", "Identificar las rutas con mayor utilización.", "Detectar posibles puntos de congestión o demora.", "Visualizar tendencias mediante gráficos o mapas.", "Elaborar conclusiones basadas en la evidencia recopilada."], "habilidades": ["Observación sistemática.", "Análisis de datos.", "Interpretación de patrones.", "Cartografía básica.", "Visualización de información.", "Investigación aplicada."], "herramientas": ["Hojas de cálculo.", "Aplicaciones de mapas.", "Herramientas de visualización de datos.", "Formularios de registro.", "Software de elaboración de mapas."], "lineamientos": ["Realiza las observaciones desde espacios públicos y seguros. No recopiles información personal ni datos que permitan identificar a individuos concretos.", "Documenta siempre cuándo, dónde y cómo se realizaron las observaciones para facilitar la interpretación de los resultados.", "Los datos obtenidos representan únicamente el periodo y las condiciones observadas, por lo que deben interpretarse dentro de ese contexto."], "otroSector": "La misma metodología puede utilizarse para analizar el flujo de clientes en un centro comercial, visitantes en un museo, usuarios de una biblioteca, vehículos en una carretera o personas dentro de un evento."}$fade5a3$::jsonb,2),
('un-mapa-de-los-lugares-que-si-son-accesibles','ciudades',array['sociedad']::text[],'Un mapa de los lugares que sí son accesibles','Imagina cómo identificar, registrar y visualizar espacios accesibles para personas con distintas necesidades de movilidad, creando una herramienta que facilite la planificación de desplazamientos y el acceso a lugares de uso cotidiano.','Guía','1 a 3 meses',52,array['Accesibilidad','Inclusión','Información geográfica']::text[],array['resolver','otro-sector']::text[],'publicos',null,'ingenieria de sistemas arquitectura urbanismo ingenieria civil diseno ux trabajo social geografia administracion publica ciencia de datos recoleccion de informacion en campo. organizacion de datos. diseno de sistemas de informacion. cartografia basica. diseno centrado en las personas. comunicacion visual. aplicaciones de mapas. formularios digitales. hojas de calculo. herramientas de visualizacion geografica. sistemas web si deseas ampliar el proyecto.',$f206ad1${"id": "un-mapa-de-los-lugares-que-si-son-accesibles", "area": "ciudades", "areas2": ["sociedad"], "titulo": "Un mapa de los lugares que sí son accesibles", "resumen": "Imagina cómo identificar, registrar y visualizar espacios accesibles para personas con distintas necesidades de movilidad, creando una herramienta que facilite la planificación de desplazamientos y el acceso a lugares de uso cotidiano.", "tipo": "Guía", "tiempo": "1 a 3 meses", "horas": 52, "etiquetas": ["Accesibilidad", "Inclusión", "Información geográfica"], "intencion": ["resolver", "otro-sector"], "datos": "publicos", "datosTexto": "observaciones propias y fuentes públicas: puedes recopilar información visitando espacios o consultando información institucional disponible.", "carreras": ["Ingeniería de Sistemas", "Arquitectura", "Urbanismo", "Ingeniería Civil", "Diseño UX", "Trabajo Social", "Geografía", "Administración Pública", "Ciencia de Datos"], "problema": ["Muchas personas dan por sentado que pueden acceder sin dificultades a edificios, comercios, instituciones o espacios públicos. Sin embargo, para alguien con movilidad reducida, una rampa inexistente, una vereda en mal estado o una entrada demasiado estrecha pueden convertirse en barreras importantes.", "Aunque algunos lugares cuentan con infraestructura accesible, esta información suele estar dispersa o simplemente no se encuentra disponible de forma sencilla. Como resultado, las personas deben averiguar por su cuenta si podrán acceder a un lugar antes de desplazarse.", "La falta de información también dificulta identificar qué espacios necesitan mejoras y cuáles ya cuentan con condiciones adecuadas de accesibilidad."], "desarrollar": ["Selecciona una zona determinada y registra información básica sobre distintos espacios.", "Por ejemplo:", {"lista": ["Existencia de rampas.", "Accesos alternativos.", "Ascensores.", "Baños accesibles.", "Señalización.", "Estado de circulación de veredas y accesos."]}, "Con los datos recopilados, construye un mapa o directorio digital que permita consultar fácilmente esta información."], "ampliaciones": [{"titulo": "Comparar zonas", "aporta": "analiza qué barrios o sectores presentan mejores condiciones de accesibilidad."}, {"titulo": "Indicadores visuales", "aporta": "diseña una forma sencilla de representar distintos niveles de accesibilidad."}, {"titulo": "Actualización colaborativa", "aporta": "imagina cómo otras personas podrían contribuir a mantener la información actualizada."}], "objetivos": ["Identificar qué elementos facilitan o dificultan la accesibilidad.", "Diseñar una metodología de registro clara y consistente.", "Organizar la información de manera comprensible.", "Crear una visualización que facilite la consulta de los datos.", "Detectar oportunidades de mejora en los espacios observados."], "habilidades": ["Recolección de información en campo.", "Organización de datos.", "Diseño de sistemas de información.", "Cartografía básica.", "Diseño centrado en las personas.", "Comunicación visual."], "herramientas": ["Aplicaciones de mapas.", "Formularios digitales.", "Hojas de cálculo.", "Herramientas de visualización geográfica.", "Sistemas web si deseas ampliar el proyecto."], "lineamientos": ["Procura registrar únicamente información observable y verificable. Evita asumir condiciones que no hayas podido confirmar directamente.", "Si utilizas fotografías, evita mostrar personas identificables y céntrate en la infraestructura del lugar.", "Cuando existan limitaciones o cambios temporales en el espacio, indícalos claramente para evitar interpretaciones incorrectas."], "otroSector": "La misma metodología puede utilizarse para crear mapas de puntos de reciclaje, espacios culturales, zonas seguras para peatones, servicios comunitarios, áreas deportivas o lugares de interés turístico."}$f206ad1$::jsonb,3),
('un-simulador-de-trafico-urbano','ciudades',array['tecnologia']::text[],'Un simulador de tráfico urbano','Imagina cómo se comporta el tráfico cuando cambian las condiciones de una ciudad. Descubre cómo influyen los semáforos, la cantidad de vehículos, la distribución de carriles y otros factores sobre la congestión, los tiempos de viaje y la utilización de las vías.','Simulación','2 a 6 meses',104,array['Modelamiento','Transporte','Sistemas complejos']::text[],array['crear','investigar','otro-sector']::text[],'publicos',null,'ingenieria de sistemas ingenieria civil ingenieria de transporte ingenieria industrial matematica estadistica ciencia de datos investigacion operativa programacion. simulacion de eventos discretos. matematica aplicada. modelamiento de sistemas. visualizacion de datos. analisis de procesos complejos. python. simpy u otras bibliotecas de simulacion. pygame o tecnologias web para visualizacion. herramientas de graficos y analisis. hojas de calculo para experimentacion inicial.',$fa96fff${"id": "un-simulador-de-trafico-urbano", "area": "ciudades", "areas2": ["tecnologia"], "titulo": "Un simulador de tráfico urbano", "resumen": "Imagina cómo se comporta el tráfico cuando cambian las condiciones de una ciudad. Descubre cómo influyen los semáforos, la cantidad de vehículos, la distribución de carriles y otros factores sobre la congestión, los tiempos de viaje y la utilización de las vías.", "tipo": "Simulación", "tiempo": "2 a 6 meses", "horas": 104, "etiquetas": ["Modelamiento", "Transporte", "Sistemas complejos"], "intencion": ["crear", "investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos y simulados: puedes utilizar información abierta sobre tránsito, planos urbanos simplificados o escenarios completamente simulados.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Civil", "Ingeniería de Transporte", "Ingeniería Industrial", "Matemática", "Estadística", "Ciencia de Datos", "Investigación Operativa"], "problema": ["Las ciudades dependen de miles de decisiones simultáneas tomadas por conductores, peatones, semáforos y sistemas de transporte. Aunque una calle pueda parecer fluida de manera individual, pequeñas alteraciones en un punto específico pueden generar efectos que se propagan a zonas mucho más amplias.", "Una intersección mal configurada, un semáforo con tiempos inadecuados o un aumento temporal de vehículos puede provocar congestiones que afectan a cientos o miles de personas. Comprender estas dinámicas resulta complicado porque el tráfico es un sistema complejo donde numerosas variables interactúan al mismo tiempo.", "Realizar cambios directamente en una ciudad real suele ser costoso y arriesgado. Por ello, los simuladores permiten experimentar con distintos escenarios antes de aplicar modificaciones en el mundo real."], "desarrollar": ["Construye un simulador capaz de representar una intersección o una pequeña red vial.", "El sistema puede incluir:", {"lista": ["Vehículos que llegan desde distintas direcciones.", "Semáforos programables.", "Carriles de circulación.", "Filas de espera.", "Tiempos de desplazamiento.", "Indicadores de congestión."]}, "Permite modificar parámetros como la duración de los semáforos, la cantidad de vehículos o la configuración de las vías para comparar diferentes escenarios."], "ampliaciones": [{"titulo": "Expandir la red vial", "aporta": "incorpora varias intersecciones conectadas y analiza cómo los problemas se propagan entre ellas."}, {"titulo": "Comparar estrategias de control", "aporta": "estudia diferentes configuraciones de semáforos y evalúa cuál reduce mejor la congestión."}, {"titulo": "Incorporar transporte público", "aporta": "analiza cómo cambian los resultados cuando se priorizan autobuses, tranvías u otros medios de transporte colectivo."}], "objetivos": ["Definir reglas básicas de circulación.", "Modelar la llegada y movimiento de vehículos.", "Implementar semáforos y sistemas de control.", "Medir indicadores como tiempos de espera y niveles de congestión.", "Comparar distintos escenarios de operación.", "Interpretar los resultados obtenidos y explicar su impacto."], "habilidades": ["Programación.", "Simulación de eventos discretos.", "Matemática aplicada.", "Modelamiento de sistemas.", "Visualización de datos.", "Análisis de procesos complejos."], "herramientas": ["Python.", "SimPy u otras bibliotecas de simulación.", "Pygame o tecnologías web para visualización.", "Herramientas de gráficos y análisis.", "Hojas de cálculo para experimentación inicial."], "lineamientos": ["Utiliza escenarios simulados o información pública adecuadamente documentada. Explica claramente los supuestos utilizados para construir el modelo y las limitaciones de la simulación.", "Recuerda que el comportamiento observado corresponde al sistema modelado y no sustituye un estudio profesional de ingeniería de tránsito. Las conclusiones deben interpretarse dentro del contexto del modelo desarrollado."], "otroSector": "La misma metodología puede aplicarse al estudio de evacuaciones, movimiento de personas en edificios, procesos logísticos, distribución de mercancías, circulación dentro de fábricas, atención de usuarios en servicios o transporte de materiales."}$fa96fff$::jsonb,4),
('un-recomendador-de-rutas-de-transporte','ciudades',array['tecnologia']::text[],'Un recomendador de rutas de transporte','Investiga cómo diferentes algoritmos pueden ayudar a encontrar rutas entre un origen y un destino considerando criterios más allá de la distancia. Descubre cómo factores como el tiempo de viaje, los transbordos, la accesibilidad o las preferencias de cada persona pueden influir en la elección de una ruta.','Prototipo','2 a 6 meses',104,array['Algoritmos','Geolocalización','Transporte']::text[],array['crear','resolver','otro-sector']::text[],'publicos',null,'ingenieria de sistemas ingenieria de transporte ingenieria civil matematica ingenieria industrial ciencia de datos geografia investigacion operativa teoria de grafos. algoritmos de busqueda. geolocalizacion. desarrollo de software. diseno de interfaces. analisis de datos espaciales. resolucion de problemas. python o javascript. networkx u otras bibliotecas de grafos. openstreetmap. bases de datos geograficas (opcional). herramientas de visualizacion cartografica. frameworks web para construir la interfaz.',$fb83f50${"id": "un-recomendador-de-rutas-de-transporte", "area": "ciudades", "areas2": ["tecnologia"], "titulo": "Un recomendador de rutas de transporte", "resumen": "Investiga cómo diferentes algoritmos pueden ayudar a encontrar rutas entre un origen y un destino considerando criterios más allá de la distancia. Descubre cómo factores como el tiempo de viaje, los transbordos, la accesibilidad o las preferencias de cada persona pueden influir en la elección de una ruta.", "tipo": "Prototipo", "tiempo": "2 a 6 meses", "horas": 104, "etiquetas": ["Algoritmos", "Geolocalización", "Transporte"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: mapas, redes de transporte y conjuntos de datos abiertos disponibles para análisis y experimentación.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Transporte", "Ingeniería Civil", "Matemática", "Ingeniería Industrial", "Ciencia de Datos", "Geografía", "Investigación Operativa"], "problema": ["Cuando una persona se desplaza por una ciudad, la ruta más corta no siempre es la más conveniente. Un recorrido puede implicar menos distancia, pero requerir más transbordos. Otro puede ser más largo, pero permitir un viaje más cómodo o rápido. Del mismo modo, lo que resulta adecuado para una persona puede no serlo para otra.", "Por ejemplo, alguien podría preferir minimizar el tiempo total de viaje, mientras que otra persona podría priorizar reducir la cantidad de cambios de transporte o evitar trayectos con muchas pendientes. Estas diferencias convierten la búsqueda de rutas en un problema más complejo de lo que parece a simple vista.", "Los sistemas modernos de navegación utilizan algoritmos capaces de analizar miles de posibilidades para recomendar alternativas según diferentes criterios. Comprender cómo funcionan estos sistemas permite descubrir cómo la tecnología ayuda a resolver problemas cotidianos de movilidad."], "desarrollar": ["Construye una herramienta capaz de representar una red de rutas conectadas y calcular caminos entre distintos puntos.", "El sistema puede incluir:", {"lista": ["Origen y destino.", "Distancia entre puntos.", "Conexiones disponibles.", "Tiempo estimado de recorrido.", "Número de transbordos.", "Comparación entre distintas alternativas."]}, "Diseña una interfaz que permita consultar rutas y visualizar los recorridos generados por el algoritmo."], "ampliaciones": [{"titulo": "Múltiples criterios", "aporta": "permite que el usuario decida si prefiere minimizar tiempo, distancia o cantidad de conexiones."}, {"titulo": "Accesibilidad", "aporta": "incorpora criterios relacionados con movilidad reducida o facilidad de acceso."}, {"titulo": "Información dinámica", "aporta": "explora cómo cambiarían las recomendaciones cuando existen retrasos, cierres de vías o congestión."}], "objetivos": ["Representar una red de transporte mediante estructuras adecuadas.", "Implementar algoritmos de búsqueda de rutas.", "Definir criterios para comparar alternativas.", "Diseñar una forma clara de mostrar los resultados.", "Evaluar cómo cambian las recomendaciones según las preferencias elegidas.", "Analizar las ventajas y limitaciones de los distintos enfoques utilizados."], "habilidades": ["Teoría de grafos.", "Algoritmos de búsqueda.", "Geolocalización.", "Desarrollo de software.", "Diseño de interfaces.", "Análisis de datos espaciales.", "Resolución de problemas."], "herramientas": ["Python o JavaScript.", "NetworkX u otras bibliotecas de grafos.", "OpenStreetMap.", "Bases de datos geográficas (opcional).", "Herramientas de visualización cartográfica.", "Frameworks web para construir la interfaz."], "lineamientos": ["Diferencia claramente entre rutas calculadas por el modelo y servicios de transporte realmente disponibles. Documenta la procedencia de los datos utilizados y especifica cuándo una ruta se basa en información simulada.", "Explica los criterios empleados por el algoritmo para generar recomendaciones y evita presentar una alternativa como universalmente mejor para todos los usuarios.", "Si trabajas con datos abiertos de transporte, indica la fecha de actualización y las posibles limitaciones de la información utilizada."], "otroSector": "La misma lógica puede aplicarse a recorridos de reparto, rutas de evacuación, planificación logística, movimiento de materiales dentro de almacenes, distribución de productos o desplazamientos dentro de instalaciones industriales de gran tamaño."}$fb83f50$::jsonb,5),
('cruces-peatonales','ciudades','{}'::text[],'Los cruces más difíciles para peatones cerca de tu centro de estudios','Observa cómo se cruza una pista cercana e imagina mejoras sencillas para que sea más segura.','Investigación','~15 h',15,array['Seguridad vial','Observación']::text[],array['investigar','resolver']::text[],'propios',null,'ingenieria civil arquitectura urbanismo ingenieria de transporte sociologia psicologia observacion sistematica croquis y planos simples argumentar una propuesta hoja de registro mapa o croquis fotografias del lugar (sin mostrar rostros)',$ffab8b6${"id": "cruces-peatonales", "area": "ciudades", "areas2": [], "titulo": "Los cruces más difíciles para peatones cerca de tu centro de estudios", "resumen": "Observa cómo se cruza una pista cercana e imagina mejoras sencillas para que sea más segura.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Seguridad vial", "Observación"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes", "carreras": ["Ingeniería Civil", "Arquitectura", "Urbanismo", "Ingeniería de Transporte", "Sociología", "Psicología"], "problema": ["Hay cruces donde las personas esperan poco, corren o cruzan por donde no deben, y rara vez se registra por qué ocurre."], "desarrollar": ["Un registro de observación por franjas horarias (cuántos cruzan, cuánto esperan, qué dificulta el paso) y un croquis con dos o tres mejoras posibles."], "ampliaciones": [{"titulo": "Observar más", "aporta": "Explora si cambia el panorama en otros días, horarios o con lluvia."}, {"titulo": "Comparar con otro lugar", "aporta": "Descubre qué hace distinto a otro cruce, de otro distrito, que sí funciona bien."}, {"titulo": "Mostrar la mejora", "aporta": "Imagina cómo se vería el cruce antes y después, con un dibujo o una maqueta sencilla."}], "objetivos": ["Elegir un cruce y definir qué observar.", "Registrar datos en distintas horas.", "Proponer mejoras viables con un croquis claro."], "habilidades": ["Observación sistemática", "Croquis y planos simples", "Argumentar una propuesta"], "herramientas": ["Hoja de registro", "Mapa o croquis", "Fotografías del lugar (sin mostrar rostros)"], "lineamientos": ["Observa desde un lugar seguro, sin invadir la vía.", "No grabes ni fotografíes a personas identificables.", "Presenta tus ideas como propuestas, no como críticas."], "otroSector": "El mismo método sirve para analizar colas en una ventanilla, el flujo en un mercado o el tránsito dentro de una planta."}$ffab8b6$::jsonb,6),
('donde-se-acumula-la-carga-academica-de-tu-semana','educacion',array['tecnologia']::text[],'¿Dónde se acumula la carga académica de tu semana?','Descubre cómo visualizar la distribución de clases, tareas, prácticas, exámenes y actividades para descubrir en qué momentos se concentra la mayor carga académica y cómo podría organizarse mejor.','Análisis','~12 h',12,array['Datos','Educación']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios',null,'ingenieria de sistemas ciencia de datos estadistica ingenieria industrial educacion administracion organizacion y analisis de datos. visualizacion de informacion. planificacion del tiempo. interpretacion de graficos. identificacion de patrones. hoja de calculo. herramientas de graficos y visualizacion. calendarios digitales. bases de datos sencillas si deseas ampliar el proyecto.',$f68af70${"id": "donde-se-acumula-la-carga-academica-de-tu-semana", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Dónde se acumula la carga académica de tu semana?", "resumen": "Descubre cómo visualizar la distribución de clases, tareas, prácticas, exámenes y actividades para descubrir en qué momentos se concentra la mayor carga académica y cómo podría organizarse mejor.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Datos", "Educación"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: puedes utilizar tu propio horario, datos inventados o cronogramas simulados de varios estudiantes.", "carreras": ["Ingeniería de Sistemas", "Ciencia de Datos", "Estadística", "Ingeniería Industrial", "Educación", "Administración"], "problema": ["Muchos estudiantes organizan sus actividades semana a semana sin una visión completa de toda la carga académica. Como consecuencia, es común que varias entregas, exposiciones, laboratorios o exámenes coincidan en los mismos días, generando periodos de alta presión seguidos de otros con poca actividad.", "En muchos casos el problema no es la cantidad total de trabajo, sino la forma en que este se distribuye. Sin datos claros resulta difícil identificar patrones, anticipar semanas complicadas o tomar decisiones para equilibrar mejor el tiempo disponible."], "desarrollar": ["Un análisis sencillo que registre cursos, actividades y fechas importantes para construir gráficos o visualizaciones que muestren la carga académica por día o por semana.", "El resultado puede ser un panel visual, una hoja de cálculo o una aplicación sencilla que ayude a detectar momentos de sobrecarga y periodos con menor demanda."], "ampliaciones": [{"titulo": "Comparar estrategias", "aporta": "analiza cómo cambia la distribución de la carga entre estudiantes con horarios distintos."}, {"titulo": "Simular escenarios", "aporta": "descubre qué ocurriría si ciertas actividades se adelantaran, retrasaran o repartieran de otra forma."}, {"titulo": "Generar alertas", "aporta": "explora cómo avisar cuando una semana comienza a concentrar demasiadas tareas o evaluaciones."}], "objetivos": ["Identificar qué tipo de actividades generan mayor carga académica.", "Diseñar una forma clara de registrar y clasificar las actividades.", "Visualizar la distribución del trabajo a lo largo del tiempo.", "Detectar patrones de acumulación o desequilibrio.", "Proponer recomendaciones para mejorar la planificación."], "habilidades": ["Organización y análisis de datos.", "Visualización de información.", "Planificación del tiempo.", "Interpretación de gráficos.", "Identificación de patrones."], "herramientas": ["Hoja de cálculo.", "Herramientas de gráficos y visualización.", "Calendarios digitales.", "Bases de datos sencillas si deseas ampliar el proyecto."], "lineamientos": ["Si utilizas información de otras personas, solicita permiso antes de recopilarla. Evita registrar datos personales innecesarios y céntrate únicamente en las actividades académicas. Recuerda que los resultados muestran tendencias y no representan necesariamente el rendimiento o la capacidad de cada estudiante."], "otroSector": "La misma metodología puede utilizarse para analizar cargas de trabajo en equipos de una empresa, distribución de proyectos de investigación, planificación de eventos o gestión de tareas en organizaciones."}$f68af70$::jsonb,0),
('como-ensenar-una-aplicacion-a-un-familiar-mayor','educacion',array['sociedad']::text[],'¿Cómo enseñar una aplicación a un familiar mayor?','Imagina cómo ayudar a una persona mayor a realizar una tarea digital cotidiana, como pedir una cita médica, hacer una consulta o pedir un taxi, y cómo convertir esa experiencia en una guía clara que otras personas también puedan usar.','Guía','~12 h',12,array['Experiencia de usuario','Educación','Inclusión']::text[],array['resolver','otro-sector']::text[],'propios',null,'educacion psicologia ingenieria de sistemas ingenieria de software comunicaciones trabajo social salud observacion de usuarios. redaccion de instrucciones claras. empatia y comunicacion. diseno de materiales educativos. accesibilidad y experiencia de usuario. editor de documentos o de presentaciones. capturas y grabacion de pantalla. herramientas de edicion de imagenes o video sencillas. aplicaciones en modo de prueba o demostracion, cuando existan.',$fc4e504${"id": "como-ensenar-una-aplicacion-a-un-familiar-mayor", "area": "educacion", "areas2": ["sociedad"], "titulo": "¿Cómo enseñar una aplicación a un familiar mayor?", "resumen": "Imagina cómo ayudar a una persona mayor a realizar una tarea digital cotidiana, como pedir una cita médica, hacer una consulta o pedir un taxi, y cómo convertir esa experiencia en una guía clara que otras personas también puedan usar.", "tipo": "Guía", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Experiencia de usuario", "Educación", "Inclusión"], "intencion": ["resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes trabajar con un familiar o vecino que quiera participar y dé su consentimiento, o con un caso inventado.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Ingeniería de Software", "Comunicaciones", "Trabajo Social", "Salud"], "problema": ["Cada vez más trámites y servicios dependen de aplicaciones: citas médicas, banca móvil, transporte, compras o comunicación con la familia. Para muchas personas mayores, estas herramientas resultan confusas: los íconos no se entienden, los textos usan palabras desconocidas y existe el temor a equivocarse o a ser víctima de una estafa.", "Con frecuencia, la ayuda de la familia se limita a explicar rápido o a hacer la tarea por ellos, lo que genera frustración en ambos lados y no ayuda a ganar autonomía."], "desarrollar": ["Elige una tarea concreta y obsérvala mientras una persona la intenta realizar. Registra en qué momentos se traba, qué palabras o botones no entiende y qué errores comete.", "A partir de eso, crea una guía paso a paso con lenguaje claro, imágenes grandes, instrucciones cortas y consejos básicos para evitar fraudes.", "El resultado puede ser una cartilla impresa, un documento digital o un video breve que se pueda ver las veces que haga falta."], "ampliaciones": [{"titulo": "Otra persona, otra necesidad", "aporta": "repite la experiencia con alguien con baja visión o que nunca usó un celular, y compara qué cambia."}, {"titulo": "Un taller breve", "aporta": "organiza una sesión pequeña para varias personas y registra las dudas más comunes."}, {"titulo": "Una guía que se reutiliza", "aporta": "convierte la cartilla en una plantilla que otros puedan adaptar a otra aplicación."}], "objetivos": ["Identificar las barreras que encuentran las personas mayores al usar una aplicación.", "Observar el uso real sin interrumpir ni corregir de inmediato.", "Diseñar instrucciones claras, breves y fáciles de seguir.", "Incluir recomendaciones de seguridad adaptadas a un lenguaje sencillo.", "Comprobar si la persona logra repetir la tarea de forma autónoma con tu guía."], "habilidades": ["Observación de usuarios.", "Redacción de instrucciones claras.", "Empatía y comunicación.", "Diseño de materiales educativos.", "Accesibilidad y experiencia de usuario."], "herramientas": ["Editor de documentos o de presentaciones.", "Capturas y grabación de pantalla.", "Herramientas de edición de imágenes o video sencillas.", "Aplicaciones en modo de prueba o demostración, cuando existan."], "lineamientos": ["Pide siempre el consentimiento de la persona y respeta su ritmo: evita hablar con ella como si fuera un niño. No pidas ni uses sus claves, y no practiques con cuentas que manejen dinero real.", "Si compartes capturas de pantalla, verifica que no muestren datos personales, números de cuenta ni mensajes privados. Presenta las recomendaciones de seguridad como buenas prácticas generales."], "otroSector": "La misma metodología puede aplicarse a capacitaciones para personal no técnico en una empresa, talleres de inclusión digital en municipalidades o centros de adultos mayores, y al diseño de servicios de salud o bancarios más fáciles de usar."}$fc4e504$::jsonb,1),
('donde-se-pierde-el-tiempo-en-un-trabajo-en-equipo','educacion',array['negocios']::text[],'¿Dónde se pierde el tiempo en un trabajo en equipo?','Explora qué sucede en un trabajo grupal desde que se asigna hasta que se entrega, en qué momentos se pierde tiempo y cómo diseñar reglas simples para que el equipo se coordine mejor sin depender de la buena voluntad de una sola persona.','Análisis','~12 h',12,array['Trabajo en equipo','Procesos','Organización']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios',null,'psicologia administracion ingenieria industrial ingenieria de sistemas ingenieria de software educacion comunicaciones analisis de procesos. comunicacion y coordinacion de equipos. diseno de plantillas y procedimientos. observacion y reflexion critica. organizacion de informacion. hoja de calculo o herramientas de lineas de tiempo. herramientas de diagramas de flujo. documentos y carpetas compartidas. tableros de tareas.',$f5ad462${"id": "donde-se-pierde-el-tiempo-en-un-trabajo-en-equipo", "area": "educacion", "areas2": ["negocios"], "titulo": "¿Dónde se pierde el tiempo en un trabajo en equipo?", "resumen": "Explora qué sucede en un trabajo grupal desde que se asigna hasta que se entrega, en qué momentos se pierde tiempo y cómo diseñar reglas simples para que el equipo se coordine mejor sin depender de la buena voluntad de una sola persona.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Trabajo en equipo", "Procesos", "Organización"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: puedes reconstruir un trabajo grupal pasado usando roles en lugar de nombres, o inventar un caso con un equipo imaginario.", "carreras": ["Psicología", "Administración", "Ingeniería Industrial", "Ingeniería de Sistemas", "Ingeniería de Software", "Educación", "Comunicaciones"], "problema": ["Casi todo estudiante ha vivido un trabajo grupal donde nadie sabía exactamente quién hacía qué, había varias versiones del mismo archivo, las reuniones terminaban sin acuerdos y todo se concentraba en las últimas horas antes de la entrega.", "Lo habitual es culpar a las personas, pero muchas veces el problema está en el proceso: falta claridad en los roles, no hay un lugar único para los archivos, no se define cuándo una tarea está terminada o las decisiones se toman por chat y se pierden entre mensajes."], "desarrollar": ["Una línea de tiempo de un trabajo grupal real o ficticio que marque cuándo se asignó cada tarea, cuándo se avanzó y cuándo ocurrieron las esperas, repeticiones de trabajo y cambios de último minuto.", "A partir de ahí, identifica los tres o cuatro puntos donde más tiempo se perdió y propone un protocolo sencillo de coordinación con roles, un lugar único para los archivos, reglas de versiones y una lista de verificación de entrega.", "El resultado puede ser un diagrama del proceso con sus puntos críticos y una plantilla lista para que otros equipos la usen."], "ampliaciones": [{"titulo": "Otro tipo de equipo", "aporta": "aplica el protocolo a un grupo distinto, como un voluntariado o un emprendimiento, y compara."}, {"titulo": "Medir si funcionó", "aporta": "usa la plantilla en un trabajo real y compara cuánto se tardó y cuántas versiones del archivo hubo."}, {"titulo": "Un tablero para el equipo", "aporta": "transforma el protocolo en una herramienta pequeña que muestre quién hace qué y qué falta."}], "objetivos": ["Reconstruir cómo se desarrolló un trabajo grupal de principio a fin.", "Identificar esperas, repeticiones y falta de decisiones.", "Distinguir los problemas de proceso de los problemas de personas.", "Diseñar un protocolo de coordinación breve y práctico.", "Comprobar si el protocolo reduce confusiones en un nuevo trabajo grupal."], "habilidades": ["Análisis de procesos.", "Comunicación y coordinación de equipos.", "Diseño de plantillas y procedimientos.", "Observación y reflexión crítica.", "Organización de información."], "herramientas": ["Hoja de cálculo o herramientas de líneas de tiempo.", "Herramientas de diagramas de flujo.", "Documentos y carpetas compartidas.", "Tableros de tareas."], "lineamientos": ["No señales ni califiques a personas concretas: trabaja con roles como \"coordinador\" o \"redactor\" y evita convertir el análisis en una lista de culpables. Si usas información real de tu grupo, pide su consentimiento antes de compartirla.", "Presenta el protocolo como una propuesta que puede adaptarse, y recuerda que ninguna plantilla reemplaza el acuerdo y el compromiso real entre las personas."], "otroSector": "La misma idea puede aplicarse a equipos de proyectos en empresas, grupos de investigación, clubes, voluntariados, equipos de desarrollo de software y cualquier trabajo donde varias personas dependan unas de otras para entregar algo."}$f5ad462$::jsonb,2),
('tus-apuntes-archivos-y-enlaces-en-un-solo-lugar','educacion',array['tecnologia','sociedad']::text[],'Tus apuntes, archivos y enlaces en un solo lugar','Imagina cómo reunir apuntes, presentaciones, PDFs, videos y enlaces en un solo lugar para encontrarlos rápidamente cuando los necesites, y cómo podrían sumarse los aportes de otras personas.','Prototipo','~20 h',20,array['Organización','Búsqueda de información','Colaboración']::text[],array['crear','resolver','otro-sector']::text[],'propios',null,'ingenieria de sistemas ingenieria de software bibliotecologia educacion comunicaciones ciencia de datos estadistica gestion de la informacion organizacion de informacion. diseno de estructuras de datos. experiencia de usuario. levantamiento de requerimientos. clasificacion y etiquetado de contenidos. hoja de calculo. formularios digitales. base de datos sencilla. herramientas web si decides crear una aplicacion.',$fe6dadb${"id": "tus-apuntes-archivos-y-enlaces-en-un-solo-lugar", "area": "educacion", "areas2": ["tecnologia", "sociedad"], "titulo": "Tus apuntes, archivos y enlaces en un solo lugar", "resumen": "Imagina cómo reunir apuntes, presentaciones, PDFs, videos y enlaces en un solo lugar para encontrarlos rápidamente cuando los necesites, y cómo podrían sumarse los aportes de otras personas.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Organización", "Búsqueda de información", "Colaboración"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes utilizar tus propios apuntes, materiales públicos o ejemplos inventados.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Bibliotecología", "Educación", "Comunicaciones", "Ciencia de Datos", "Estadística", "Gestión de la Información"], "problema": ["A medida que avanzan los ciclos académicos, los materiales terminan repartidos entre carpetas, correos electrónicos, grupos de mensajería y plataformas distintas. Muchas veces un estudiante recuerda haber guardado un recurso útil, pero no recuerda dónde. El resultado es tiempo perdido, duplicación de archivos y materiales valiosos que terminan olvidados.", "Cuando varias personas comparten materiales, el problema se multiplica: los mismos recursos se piden una y otra vez, se generan duplicados y nadie sabe cuál sigue siendo útil o vigente."], "desarrollar": ["Un sistema sencillo que permita registrar recursos, clasificarlos por curso, tema o tipo de contenido y encontrarlos mediante filtros básicos. Puede implementarse como una hoja de cálculo organizada, una base de datos simple o una pequeña aplicación web.", "Cada recurso puede incluir información como título, descripción, fecha, etiquetas y nivel de utilidad."], "ampliaciones": [{"titulo": "Mejor búsqueda", "aporta": "explora cómo encontrar materiales incluso cuando no recuerdas el nombre exacto del archivo."}, {"titulo": "Biblioteca compartida", "aporta": "imagina un espacio donde varias personas aporten materiales, indiquen cuáles les resultaron más útiles y señalen cuáles ya están desactualizados."}, {"titulo": "Recomendaciones", "aporta": "descubre cómo sugerir recursos relacionados según el tema consultado."}], "objetivos": ["Identificar cómo se almacenan actualmente los materiales de estudio.", "Diseñar una estructura de categorías que facilite la búsqueda.", "Construir un sistema de registro sencillo.", "Comprobar si realmente reduce el tiempo necesario para encontrar información.", "Analizar cómo evitar duplicados y mantener la información organizada."], "habilidades": ["Organización de información.", "Diseño de estructuras de datos.", "Experiencia de usuario.", "Levantamiento de requerimientos.", "Clasificación y etiquetado de contenidos."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Base de datos sencilla.", "Herramientas web si decides crear una aplicación."], "lineamientos": ["Empieza con una cantidad reducida de materiales antes de intentar organizar cientos de archivos. Prioriza la facilidad de búsqueda sobre la cantidad de funciones.", "Si compartes recursos de terceros, respeta siempre sus permisos de distribución y los derechos de autor. Evita almacenar archivos innecesarios cuando basten enlaces o referencias."], "otroSector": "La misma idea puede utilizarse para organizar artículos científicos, documentación técnica, expedientes digitales, repositorios de proyectos o recursos educativos institucionales."}$fe6dadb$::jsonb,3),
('el-primer-dia-de-un-ingresante-como-se-orienta-en-su-centro-de-e','educacion',array['tecnologia']::text[],'El primer día de un ingresante: ¿cómo se orienta en su centro de estudios?','Imagina cómo ayudar a una persona que llega por primera vez a un lugar grande y desconocido a encontrar su salón, la biblioteca, los baños, la cafetería o la oficina de trámites sin sentirse perdida ni depender de preguntar a cada persona que encuentre.','Prototipo','~20 h',20,array['Orientación','Experiencia de usuario','Accesibilidad']::text[],array['crear','resolver','otro-sector']::text[],'propios',null,'arquitectura ingenieria civil educacion comunicaciones ingenieria de sistemas psicologia diseno trabajo social observacion de usuarios. diseno de informacion y senalizacion. accesibilidad y diseno inclusivo. representacion espacial y elaboracion de mapas. redaccion clara de instrucciones. herramientas de dibujo o diseno grafico. mapas digitales para tomar referencias del espacio. editor de documentos o presentaciones. herramientas web basicas si deseas crear una version interactiva.',$f010d7e${"id": "el-primer-dia-de-un-ingresante-como-se-orienta-en-su-centro-de-e", "area": "educacion", "areas2": ["tecnologia"], "titulo": "El primer día de un ingresante: ¿cómo se orienta en su centro de estudios?", "resumen": "Imagina cómo ayudar a una persona que llega por primera vez a un lugar grande y desconocido a encontrar su salón, la biblioteca, los baños, la cafetería o la oficina de trámites sin sentirse perdida ni depender de preguntar a cada persona que encuentre.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Orientación", "Experiencia de usuario", "Accesibilidad"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes usar tu propio centro de estudios, un espacio imaginario o el plano de un lugar público como un centro comercial o un hospital.", "carreras": ["Arquitectura", "Ingeniería Civil", "Educación", "Comunicaciones", "Ingeniería de Sistemas", "Psicología", "Diseño", "Trabajo Social"], "problema": ["El primer día en un centro de estudios nuevo suele ser abrumador: pabellones con nombres parecidos, pisos que no siguen una lógica evidente, carteles que solo entiende quien ya conoce el lugar y planos que muestran todo menos lo que la persona necesita en ese momento.", "Esto se nota más en quienes llegan con prisa, tienen movilidad reducida, no conocen la ciudad o visitan el lugar solo una vez. Muchas personas llegan tarde, se frustran o terminan dependiendo de la suerte de encontrar a alguien amable que las guíe."], "desarrollar": ["Elige un recorrido típico, como llegar desde la puerta principal hasta un salón específico, y recórrelo como si fuera la primera vez, anotando dónde dudas, qué carteles ayudan y cuáles confunden.", "A partir de eso, crea una guía de orientación que incluya un mapa simplificado con los puntos clave, instrucciones cortas basadas en referencias visibles y una versión pensada para personas con movilidad reducida.", "El resultado puede ser un plano ilustrado, una guía impresa, una página web móvil o una presentación fácil de consultar desde el celular."], "ampliaciones": [{"titulo": "Probar con personas reales", "aporta": "pide a alguien que nunca ha estado allí que siga tu guía y registra en qué puntos se detiene o se equivoca."}, {"titulo": "Rutas alternativas", "aporta": "diseña recorridos distintos según la necesidad, como el camino más corto, el más accesible o el que pasa por zonas con sombra."}, {"titulo": "Versión interactiva", "aporta": "explora cómo crear un mapa digital donde la persona seleccione su destino y reciba indicaciones paso a paso."}], "objetivos": ["Identificar los puntos de un centro de estudios donde una persona nueva suele desorientarse.", "Evaluar qué elementos de señalización ayudan y cuáles generan confusión.", "Diseñar un mapa simplificado centrado en lo que la persona necesita.", "Redactar indicaciones claras basadas en referencias visibles.", "Comprobar si la guía funciona con alguien que no conoce el lugar."], "habilidades": ["Observación de usuarios.", "Diseño de información y señalización.", "Accesibilidad y diseño inclusivo.", "Representación espacial y elaboración de mapas.", "Redacción clara de instrucciones."], "herramientas": ["Herramientas de dibujo o diseño gráfico.", "Mapas digitales para tomar referencias del espacio.", "Editor de documentos o presentaciones.", "Herramientas web básicas si deseas crear una versión interactiva."], "lineamientos": ["Respeta las normas del lugar y no ingreses a zonas restringidas mientras haces el recorrido. Si pruebas la guía con otras personas, pide su consentimiento y evita fotografiarlas o recopilar datos personales.", "Si usas el nombre o el plano oficial de una institución, aclara que tu proyecto es independiente y no una guía oficial. Verifica que las rutas accesibles realmente lo sean antes de recomendarlas."], "otroSector": "La misma idea puede aplicarse a hospitales, terminales de transporte, museos, centros comerciales, ferias, congresos o cualquier espacio donde las personas lleguen por primera vez y necesiten ubicarse con rapidez."}$f010d7e$::jsonb,4),
('costo-taller-escolar','educacion','{}'::text[],'¿Cuánto cuesta realmente un taller escolar?','Descubre cómo costear materiales, tiempo y local de una actividad para proponer un precio justo con una hoja de costos.','Análisis','~8 h',8,array['Costos','Educación']::text[],array['investigar','resolver']::text[],'publicos',null,'educacion administracion contabilidad psicologia economia costeo planificacion de actividades comunicacion clara hoja de calculo',$f614690${"id": "costo-taller-escolar", "area": "educacion", "areas2": [], "titulo": "¿Cuánto cuesta realmente un taller escolar?", "resumen": "Descubre cómo costear materiales, tiempo y local de una actividad para proponer un precio justo con una hoja de costos.", "tipo": "Análisis", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Costos", "Educación"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: salen de fuentes abiertas", "carreras": ["Educación", "Administración", "Contabilidad", "Psicología", "Economía"], "problema": ["Quienes organizan talleres o actividades educativas suelen calcular el costo «a ojo», y terminan cobrando de menos o dejando fuera partes importantes."], "desarrollar": ["Una hoja de costos para un taller concreto: materiales, tiempo de preparación, uso del local y un margen razonable, con un precio sugerido por participante."], "objetivos": ["Listar todo lo que necesita un taller para realizarse.", "Calcular el costo por participante.", "Explicar cómo cambia el precio según la cantidad de asistentes."], "habilidades": ["Costeo", "Planificación de actividades", "Comunicación clara"], "herramientas": ["Hoja de cálculo"], "lineamientos": ["Elige un taller que conozcas bien.", "Separa lo que es costo real de lo que es opcional.", "Muestra siempre el cálculo, no solo el resultado."], "otroSector": "El mismo cálculo sirve para una feria, un campamento, un curso de verano o un evento cultural."}$f614690$::jsonb,5),
('como-reconocer-una-noticia-sospechosa-en-internet','sociedad',array['educacion','tecnologia']::text[],'¿Cómo reconocer una noticia sospechosa en internet?','Imagina cómo evaluar la confiabilidad de una noticia, publicación o contenido digital antes de compartirlo. Descubre qué señales pueden indicar que una información necesita verificarse y diseña una guía práctica que ayude a otras personas a tomar decisiones mejor informadas.','Guía','1 a 4 semanas',15,array['Alfabetización digital','Verificación','Pensamiento crítico']::text[],array['resolver','otro-sector']::text[],'publicos',null,'comunicaciones periodismo derecho educacion ingenieria de sistemas ciencia de datos psicologia ciencias politicas marketing busqueda de informacion. pensamiento critico. verificacion de fuentes. comunicacion visual. alfabetizacion digital. organizacion de contenidos. navegador web. fuentes de verificacion publicas. herramientas de diseno o presentaciones. aplicaciones para elaborar infografias. herramientas de busqueda de imagenes (opcional).',$f6b5b3e${"id": "como-reconocer-una-noticia-sospechosa-en-internet", "area": "sociedad", "areas2": ["educacion", "tecnologia"], "titulo": "¿Cómo reconocer una noticia sospechosa en internet?", "resumen": "Imagina cómo evaluar la confiabilidad de una noticia, publicación o contenido digital antes de compartirlo. Descubre qué señales pueden indicar que una información necesita verificarse y diseña una guía práctica que ayude a otras personas a tomar decisiones mejor informadas.", "tipo": "Guía", "tiempo": "1 a 4 semanas", "horas": 15, "etiquetas": ["Alfabetización digital", "Verificación", "Pensamiento crítico"], "intencion": ["resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: puedes utilizar publicaciones, artículos, imágenes y fuentes abiertas disponibles en internet.", "carreras": ["Comunicaciones", "Periodismo", "Derecho", "Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Ciencias Políticas", "Marketing"], "problema": ["Cada día circulan miles de publicaciones en redes sociales, aplicaciones de mensajería, blogs y sitios web. Algunas contienen información correcta y verificable, pero otras presentan datos incompletos, imágenes sacadas de contexto, titulares engañosos o afirmaciones sin evidencia suficiente.", "La rapidez con la que se comparte información hace que muchas personas difundan contenidos sin comprobar quién los publicó, cuándo se publicó o si existen fuentes confiables que respalden lo que se afirma.", "En algunos casos el problema no es que una noticia sea completamente falsa, sino que presenta información incompleta, desactualizada o fuera de contexto. Por eso resulta importante desarrollar habilidades que permitan analizar críticamente lo que vemos antes de aceptarlo o compartirlo."], "desarrollar": ["Diseña una guía visual sencilla que ayude a revisar una noticia paso a paso antes de compartirla.", "Por ejemplo, la guía puede incluir preguntas como:", {"lista": ["¿Quién publicó la información?", "¿Cuál es la fuente original?", "¿Cuándo fue publicada?", "¿Otras fuentes confiables informan lo mismo?", "¿La imagen pertenece realmente al hecho que se describe?", "¿Existen evidencias que respalden la afirmación?"]}, "Presenta las comprobaciones mediante diagramas, tarjetas visuales, una infografía o una página interactiva fácil de consultar."], "ampliaciones": [{"titulo": "Casos prácticos", "aporta": "desarrolla ejemplos simulados para mostrar cómo aplicar el proceso de verificación."}, {"titulo": "Versiones especializadas", "aporta": "adapta la guía a temas específicos como salud, tecnología, economía o ciencia."}, {"titulo": "Diseño interactivo", "aporta": "transforma las comprobaciones en una herramienta donde los usuarios respondan preguntas y reciban recomendaciones para verificar la información."}], "objetivos": ["Identificar señales que justifican una verificación adicional.", "Investigar métodos básicos de comprobación de información.", "Organizar el proceso de verificación de forma clara y comprensible.", "Explicar ejemplos utilizando lenguaje sencillo.", "Crear un recurso educativo que pueda ser utilizado por otras personas."], "habilidades": ["Búsqueda de información.", "Pensamiento crítico.", "Verificación de fuentes.", "Comunicación visual.", "Alfabetización digital.", "Organización de contenidos."], "herramientas": ["Navegador web.", "Fuentes de verificación públicas.", "Herramientas de diseño o presentaciones.", "Aplicaciones para elaborar infografías.", "Herramientas de búsqueda de imágenes (opcional)."], "lineamientos": ["No clasifiques automáticamente una publicación como falsa únicamente porque provenga de una fuente desconocida. Diferencia claramente entre información falsa, engañosa, incompleta, desactualizada o simplemente no verificada.", "Utiliza ejemplos públicos o simulados y cita las fuentes que emplees para elaborar la guía. El objetivo es enseñar un proceso de análisis, no emitir juicios sobre personas o grupos específicos."], "otroSector": "La misma metodología puede aplicarse para evaluar ofertas de empleo, anuncios comerciales, información sobre productos, recomendaciones de salud, publicaciones financieras, estudios científicos o contenidos generados por inteligencia artificial."}$f6b5b3e$::jsonb,0),
('como-se-propaga-un-rumor-en-el-grupo-de-tu-carrera','sociedad',array['tecnologia']::text[],'¿Cómo se propaga un rumor en el grupo de tu carrera?','Descubre cómo un mensaje, verdadero o falso, puede pasar de persona en persona hasta llegar a cientos, y por qué las correcciones suelen alcanzar a mucha menos gente que el rumor original.','Simulación','~25 h',25,array['Simulación','Redes','Comunicación']::text[],array['crear','investigar','otro-sector']::text[],'ficticios',null,'matematica estadistica ingenieria de sistemas comunicaciones sociologia psicologia ciencia de datos fisica modelado y simulacion. redes y grafos. probabilidad basica. visualizacion de datos. pensamiento critico sobre la informacion. hoja de calculo. lenguajes de programacion como python. herramientas de simulacion o de visualizacion de redes. herramientas web basicas si deseas crear una version interactiva.',$f6f18fb${"id": "como-se-propaga-un-rumor-en-el-grupo-de-tu-carrera", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "¿Cómo se propaga un rumor en el grupo de tu carrera?", "resumen": "Descubre cómo un mensaje, verdadero o falso, puede pasar de persona en persona hasta llegar a cientos, y por qué las correcciones suelen alcanzar a mucha menos gente que el rumor original.", "tipo": "Simulación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Simulación", "Redes", "Comunicación"], "intencion": ["crear", "investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o simulados: puedes construir una red inventada de personas y grupos, sin utilizar conversaciones reales ni información de nadie.", "carreras": ["Matemática", "Estadística", "Ingeniería de Sistemas", "Comunicaciones", "Sociología", "Psicología", "Ciencia de Datos", "Física"], "problema": ["En grupos de mensajería, redes sociales y comunidades estudiantiles, un mensaje reenviado puede extenderse en minutos. Cada persona lo comparte porque le parece importante, urgente o interesante, y casi nadie se detiene a verificar su origen.", "Cuando se descubre que la información era errónea, la corrección llega tarde y a menos personas. El resultado es que mucha gente se queda con la primera versión, aunque después se desmienta.", "Entender cómo ocurre esa propagación ayuda a diseñar mejores formas de comunicar y a reconocer en qué momentos un mensaje puede frenarse."], "desarrollar": ["Una simulación sencilla en la que se represente una red de personas conectadas y se defina con qué probabilidad cada una reenvía un mensaje que recibe.", "El proyecto compara qué ocurre con un rumor y con una corrección que parte después, y muestra con gráficos cuántas personas alcanza cada uno a lo largo del tiempo.", "El resultado puede ser una hoja de cálculo con fórmulas, un programa sencillo o una pequeña página web interactiva donde se puedan cambiar los parámetros y observar el efecto."], "ampliaciones": [{"titulo": "Otra mirada", "aporta": "compara cómo se propaga un rumor con un contagio o un video viral y qué tienen en común."}, {"titulo": "Cortar el rumor", "aporta": "evalúa qué corrección alcanza a más gente, si la más rápida, la más clara o la que viene de alguien conocido."}, {"titulo": "Pensar antes de reenviar", "aporta": "crea una guía corta para quien recibe un mensaje dudoso y quiere decidir con calma."}], "objetivos": ["Representar una comunidad como una red de personas conectadas.", "Definir reglas simples de cómo se comparte un mensaje.", "Simular la propagación de un rumor y de su corrección.", "Analizar qué factores aceleran o frenan la difusión.", "Reflexionar sobre qué estrategias podrían hacer que las correcciones lleguen mejor."], "habilidades": ["Modelado y simulación.", "Redes y grafos.", "Probabilidad básica.", "Visualización de datos.", "Pensamiento crítico sobre la información."], "herramientas": ["Hoja de cálculo.", "Lenguajes de programación como Python.", "Herramientas de simulación o de visualización de redes.", "Herramientas web básicas si deseas crear una versión interactiva."], "lineamientos": ["Trabaja únicamente con redes simuladas: no analices conversaciones reales, no uses nombres de personas reales ni recopiles mensajes de grupos. Evita tomar como ejemplo rumores reales que puedan perjudicar a alguien.", "Recuerda que una simulación es una simplificación: sirve para entender tendencias, no para predecir con exactitud cómo se comportará una comunidad real."], "otroSector": "La misma idea puede utilizarse para estudiar la difusión de campañas de salud, el alcance de un anuncio, la comunicación durante una crisis o el contagio de enfermedades en una población."}$f6f18fb$::jsonb,1),
('una-colecta-solidaria-sin-caos-de-la-donacion-a-la-entrega','sociedad',array['tecnologia']::text[],'Una colecta solidaria sin caos: de la donación a la entrega','Explora cómo coordinar una colecta de abrigo, útiles escolares o alimentos para que las donaciones lleguen a quien las necesita sin perderse, duplicarse ni quedar acumuladas en un rincón mientras faltan otras cosas.','Prototipo','1 a 2 meses',39,array['Logística','Voluntariado','Impacto social']::text[],array['crear','resolver','otro-sector']::text[],'ficticios',null,'trabajo social ingenieria industrial ingenieria de sistemas administracion comunicaciones educacion ingenieria civil psicologia logistica y planificacion. organizacion de voluntariado. registro y control de inventarios. comunicacion y transparencia. sensibilidad social y trabajo con comunidades. hoja de calculo. formularios digitales. tableros de tareas. herramientas de mapas para planificar puntos de recojo. herramientas web basicas si deseas crear un panel de seguimiento.',$f15dfd0${"id": "una-colecta-solidaria-sin-caos-de-la-donacion-a-la-entrega", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "Una colecta solidaria sin caos: de la donación a la entrega", "resumen": "Explora cómo coordinar una colecta de abrigo, útiles escolares o alimentos para que las donaciones lleguen a quien las necesita sin perderse, duplicarse ni quedar acumuladas en un rincón mientras faltan otras cosas.", "tipo": "Prototipo", "tiempo": "1 a 2 meses", "horas": 39, "etiquetas": ["Logística", "Voluntariado", "Impacto social"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o con permiso: puedes simular una campaña con donantes, voluntarios y puntos de entrega inventados, o apoyar una iniciativa real solo si sus organizadores lo autorizan y no se exponen datos personales.", "carreras": ["Trabajo Social", "Ingeniería Industrial", "Ingeniería de Sistemas", "Administración", "Comunicaciones", "Educación", "Ingeniería Civil", "Psicología"], "problema": ["Las campañas solidarias suelen nacer con mucha energía y poca organización: llegan más abrigos de los necesarios y faltan útiles, nadie sabe cuántas cosas se recibieron, los voluntarios se enteran de los horarios por mensajes sueltos y quienes donan no saben si su aporte fue útil.", "Al final, el esfuerzo de muchas personas puede perderse por falta de registro, de coordinación o de comunicación. Y cuando falla la confianza, cuesta que la gente vuelva a participar."], "desarrollar": ["Un sistema sencillo para organizar una campaña que registre qué se necesita y en qué cantidad, qué se va recibiendo, quién se encarga de cada tarea y cuándo y dónde se entregará.", "Debe permitir ver de un vistazo el avance de la campaña, qué falta todavía y un resumen final que muestre con claridad el resultado.", "El resultado puede ser una hoja de cálculo con formularios, un tablero de seguimiento o una pequeña aplicación web."], "ampliaciones": [{"titulo": "Equilibrar necesidades", "aporta": "explora cómo sugerir qué conviene donar según lo que aún falta."}, {"titulo": "Rutas de recojo", "aporta": "analiza cómo organizar recogidas en distintos puntos con la menor cantidad de recorridos posible."}, {"titulo": "Rendición de cuentas", "aporta": "diseña un reporte público y claro que muestre qué se recibió y qué se entregó, sin exponer datos de nadie."}], "objetivos": ["Identificar las necesidades reales antes de pedir donaciones.", "Diseñar un registro claro de lo que se recibe y se entrega.", "Coordinar voluntarios, tareas y horarios.", "Comunicar el avance de la campaña de manera transparente.", "Evaluar qué se logró y qué se puede mejorar en la siguiente campaña."], "habilidades": ["Logística y planificación.", "Organización de voluntariado.", "Registro y control de inventarios.", "Comunicación y transparencia.", "Sensibilidad social y trabajo con comunidades."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Tableros de tareas.", "Herramientas de mapas para planificar puntos de recojo.", "Herramientas web básicas si deseas crear un panel de seguimiento."], "lineamientos": ["No recolectes dinero ni administres fondos sin acuerdos claros y una persona o entidad responsable que respalde la campaña. Coordina con organizaciones o personas que conozcan de cerca las necesidades reales, y no asumas lo que necesita una comunidad sin preguntarle.", "Protege la privacidad de quienes reciben la ayuda: no publiques nombres, direcciones ni fotografías sin su consentimiento. Lleva un registro honesto de lo recibido y lo entregado."], "otroSector": "La misma idea puede aplicarse a bancos de alimentos, campañas de salud, colectas universitarias, reparto de ayuda tras una emergencia, ferias de intercambio o cualquier iniciativa que dependa de personas voluntarias y recursos limitados."}$f15dfd0$::jsonb,2),
('servicios-gratuitos','sociedad','{}'::text[],'Un mapa de servicios gratuitos de tu distrito','Descubre cómo reunir en un solo lugar dónde conseguir ayuda, orientación y servicios sin costo cerca de ti.','Guía','~10 h',10,array['Comunidad','Información útil']::text[],array['crear','resolver']::text[],'publicos',null,'trabajo social sociologia derecho comunicaciones ingenieria de sistemas educacion busqueda y verificacion de fuentes organizacion de la informacion diseno de guias hoja de calculo un mapa en linea un documento o una pagina sencilla',$fd73298${"id": "servicios-gratuitos", "area": "sociedad", "areas2": [], "titulo": "Un mapa de servicios gratuitos de tu distrito", "resumen": "Descubre cómo reunir en un solo lugar dónde conseguir ayuda, orientación y servicios sin costo cerca de ti.", "tipo": "Guía", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Comunidad", "Información útil"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: salen de fuentes abiertas", "carreras": ["Trabajo Social", "Sociología", "Derecho", "Comunicaciones", "Ingeniería de Sistemas", "Educación"], "problema": ["Existen servicios gratuitos de salud, orientación legal, apoyo escolar o cultura, pero la información está dispersa y mucha gente no sabe que existen."], "desarrollar": ["Un directorio ordenado por tema y ubicación, con horarios, requisitos y cómo llegar, presentado como un mapa o una guía fácil de compartir."], "objetivos": ["Recopilar información pública y verificada.", "Organizarla para que se encuentre en pocos pasos.", "Revisarla con alguien que no conozca el tema."], "habilidades": ["Búsqueda y verificación de fuentes", "Organización de la información", "Diseño de guías"], "herramientas": ["Hoja de cálculo", "Un mapa en línea", "Un documento o una página sencilla"], "lineamientos": ["Usa solo información pública y cita la fuente.", "Indica la fecha de la última revisión.", "No publiques datos de contacto de personas, solo de instituciones."], "otroSector": "Se adapta a guías para estudiantes nuevos, para migrantes, para adultos mayores o para emprendedores."}$fd73298$::jsonb,3),
('que-tan-facil-es-entender-un-tramite-publico','derecho',array['tecnologia']::text[],'¿Qué tan fácil es entender un trámite público?','Descubre cómo una persona experimenta un trámite desde el momento en que decide realizarlo hasta que logra completarlo, identificando los pasos que generan dudas, frustración o abandono, y proponiendo formas más claras de comunicar la información.','Investigación','1 a 4 meses',65,array['Experiencia de usuario','Servicios ciudadanos','Diseño de información']::text[],array['investigar','otro-sector']::text[],'publicos',null,'ingenieria de sistemas diseno ux derecho administracion publica comunicaciones ciencias politicas sociologia economia gestion publica investigacion de usuarios. diseno de servicios. experiencia de usuario (ux). organizacion de informacion. comunicacion clara. analisis de procesos. pensamiento critico. diagramas de flujo. hojas de calculo. herramientas de diseno. aplicaciones de mapas de experiencia. formularios y entrevistas (opcionales). documentacion publica oficial.',$f0b803f${"id": "que-tan-facil-es-entender-un-tramite-publico", "area": "derecho", "areas2": ["tecnologia"], "titulo": "¿Qué tan fácil es entender un trámite público?", "resumen": "Descubre cómo una persona experimenta un trámite desde el momento en que decide realizarlo hasta que logra completarlo, identificando los pasos que generan dudas, frustración o abandono, y proponiendo formas más claras de comunicar la información.", "tipo": "Investigación", "tiempo": "1 a 4 meses", "horas": 65, "etiquetas": ["Experiencia de usuario", "Servicios ciudadanos", "Diseño de información"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: puedes utilizar información disponible en portales institucionales, guías oficiales, formularios, reglamentos y documentación accesible al público.", "carreras": ["Ingeniería de Sistemas", "Diseño UX", "Derecho", "Administración Pública", "Comunicaciones", "Ciencias Políticas", "Sociología", "Economía", "Gestión Pública"], "problema": ["Cada año, miles de personas realizan trámites relacionados con educación, salud, identificación, emprendimiento, vivienda, transporte y otros servicios. Aunque gran parte de la información necesaria suele estar disponible, muchas veces se encuentra distribuida entre distintas páginas, documentos, formularios y normativas difíciles de comprender para alguien que realiza el proceso por primera vez.", "Como consecuencia, es frecuente que las personas pierdan tiempo buscando información, repitan pasos innecesarios, presenten documentos incorrectos o abandonen el trámite por no comprender qué deben hacer a continuación.", "En muchos casos el problema no es el trámite en sí, sino la forma en que se comunica. Un proceso puede ser relativamente sencillo desde el punto de vista administrativo y, aun así, resultar confuso para los ciudadanos.", "Comprender dónde aparecen estas dificultades permite identificar oportunidades para mejorar la experiencia de quienes utilizan los servicios públicos."], "desarrollar": ["Selecciona un trámite específico y documenta la experiencia completa de una persona ficticia que intenta realizarlo.", "Por ejemplo:", {"lista": ["Solicitar un documento de identidad.", "Postular a una beca.", "Registrar un pequeño negocio.", "Solicitar un permiso municipal.", "Acceder a un programa de apoyo.", "Realizar un trámite educativo."]}, "Registra cada paso del proceso, los documentos solicitados, las decisiones que debe tomar el usuario y los posibles puntos de confusión.", "Finalmente, desarrolla una representación visual o una guía simplificada que permita comprender el trámite de manera más clara."], "objetivos": ["Identificar todas las etapas de un trámite.", "Analizar qué información necesita una persona en cada paso.", "Detectar barreras de comprensión y puntos de confusión.", "Diseñar una representación más clara del proceso.", "Elaborar recomendaciones para mejorar la experiencia del usuario."], "habilidades": ["Investigación de usuarios.", "Diseño de servicios.", "Experiencia de usuario (UX).", "Organización de información.", "Comunicación clara.", "Análisis de procesos.", "Pensamiento crítico."], "herramientas": ["Diagramas de flujo.", "Hojas de cálculo.", "Herramientas de diseño.", "Aplicaciones de mapas de experiencia.", "Formularios y entrevistas (opcionales).", "Documentación pública oficial."], "lineamientos": ["Utiliza únicamente información pública y vigente. Cita siempre las fuentes utilizadas y diferencia claramente entre información oficial y tus propuestas de mejora.", "Evita interpretar normativa o brindar asesoría legal. El objetivo es analizar cómo se comunica el proceso y cómo puede comprenderse mejor, no reemplazar la información oficial.", "Documenta los supuestos realizados y explica las limitaciones del análisis cuando existan cambios frecuentes en los requisitos o procedimientos."], "otroSector": "La misma metodología puede aplicarse al análisis de procesos empresariales, solicitudes de empleo, admisiones universitarias, inscripciones a eventos, procesos de atención médica, plataformas digitales o cualquier servicio que requiera seguir una serie de pasos."}$f0b803f$::jsonb,0),
('derechos-consumidor','derecho','{}'::text[],'Guía visual de derechos del consumidor','Descubre cómo convertir situaciones cotidianas, como compras en línea y garantías, en una guía visual lista para compartir.','Guía','~10 h',10,array['Divulgación','Derechos']::text[],array['crear','resolver']::text[],'publicos',null,'derecho comunicaciones diseno grafico economia administracion lectura de normas redaccion sencilla diseno de piezas graficas un editor de presentaciones o de diseno fuentes oficiales de proteccion al consumidor',$fb79c26${"id": "derechos-consumidor", "area": "derecho", "areas2": [], "titulo": "Guía visual de derechos del consumidor", "resumen": "Descubre cómo convertir situaciones cotidianas, como compras en línea y garantías, en una guía visual lista para compartir.", "tipo": "Guía", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Divulgación", "Derechos"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: salen de fuentes abiertas", "carreras": ["Derecho", "Comunicaciones", "Diseño Gráfico", "Economía", "Administración"], "problema": ["Mucha gente no reclama porque no sabe qué derechos tiene al comprar, devolver o pedir una garantía, o cree que el trámite es demasiado complicado."], "desarrollar": ["Una guía breve y visual que explique, con ejemplos de la vida diaria, qué se puede hacer y ante quién, usando lenguaje claro y sin tecnicismos."], "ampliaciones": [{"titulo": "Otro formato", "aporta": "Descubre cómo convertir la guía en tarjetas para redes o en un video corto."}, {"titulo": "Otro público", "aporta": "Explora cómo explicarla a quien compra en línea por primera vez o a personas mayores."}, {"titulo": "Casos simulados", "aporta": "Imagina un reclamo paso a paso, con un ejemplo ficticio, para ver cómo se vive de principio a fin."}], "objetivos": ["Elegir cuatro situaciones frecuentes.", "Explicar cada una en pocas líneas con base en fuentes oficiales.", "Comprobar que alguien ajeno al tema la entiende."], "habilidades": ["Lectura de normas", "Redacción sencilla", "Diseño de piezas gráficas"], "herramientas": ["Un editor de presentaciones o de diseño", "Fuentes oficiales de protección al consumidor"], "lineamientos": ["Cita la norma o la institución de la que tomas cada dato.", "Aclara que es información general y no asesoría legal.", "Revisa que la información siga vigente."], "otroSector": "El mismo formato sirve para derechos laborales, de los estudiantes, de los pacientes o de los inquilinos."}$fb79c26$::jsonb,1),
('dureza-agua','ciencias','{}'::text[],'Comparar la dureza del agua en distintos lugares','Explora cómo medir y comparar el agua de varios lugares con un experimento sencillo, y qué la hace diferente.','Investigación','~12 h',12,array['Experimento','Datos']::text[],array['investigar']::text[],'propios',null,'quimica fisica biologia ingenieria quimica ingenieria ambiental matematica metodo cientifico registro de datos interpretacion de graficos tiras reactivas o kit de laboratorio basico hoja de calculo',$f7c6bad${"id": "dureza-agua", "area": "ciencias", "areas2": [], "titulo": "Comparar la dureza del agua en distintos lugares", "resumen": "Explora cómo medir y comparar el agua de varios lugares con un experimento sencillo, y qué la hace diferente.", "tipo": "Investigación", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Experimento", "Datos"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes", "carreras": ["Química", "Física", "Biología", "Ingeniería Química", "Ingeniería Ambiental", "Matemática"], "problema": ["Usamos agua a diario, pero casi nadie sabe qué tan diferente es entre un lugar y otro ni cómo afecta a los electrodomésticos o al sabor."], "desarrollar": ["Un procedimiento sencillo con tiras de prueba o una titulación básica para comparar muestras, con un registro ordenado y un gráfico de resultados."], "objetivos": ["Plantear una pregunta concreta y una forma de medirla.", "Tomar y registrar las muestras con el mismo método.", "Interpretar las diferencias y sus posibles causas."], "habilidades": ["Método científico", "Registro de datos", "Interpretación de gráficos"], "herramientas": ["Tiras reactivas o kit de laboratorio básico", "Hoja de cálculo"], "lineamientos": ["Usa solo materiales seguros y sigue las indicaciones de cada kit.", "Anota cómo y cuándo tomaste cada muestra.", "No concluyas más de lo que tus datos permiten."], "otroSector": "El mismo enfoque sirve para comparar suelos, alimentos, materiales de construcción o productos de limpieza."}$f7c6bad$::jsonb,0),
('senaletica-espacio','arte','{}'::text[],'Rediseñar la señalética de un espacio de tu universidad','Imagina cómo orientar mejor a quienes se pierden en un espacio, y prueba tus señales con un prototipo.','Diseño','~15 h',15,array['Diseño gráfico','Experiencia de usuario']::text[],array['crear','resolver']::text[],'propios',null,'arquitectura diseno grafico comunicaciones psicologia ingenieria de sistemas observacion diseno grafico basico pruebas con usuarios un editor de diseno planos o croquis del lugar impresiones de prueba',$fc27d33${"id": "senaletica-espacio", "area": "arte", "areas2": [], "titulo": "Rediseñar la señalética de un espacio de tu universidad", "resumen": "Imagina cómo orientar mejor a quienes se pierden en un espacio, y prueba tus señales con un prototipo.", "tipo": "Diseño", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Diseño gráfico", "Experiencia de usuario"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes", "carreras": ["Arquitectura", "Diseño Gráfico", "Comunicaciones", "Psicología", "Ingeniería de Sistemas"], "problema": ["Hay lugares donde los visitantes y los alumnos nuevos no encuentran lo que buscan, y las señales existentes son confusas, pequeñas o inexistentes."], "desarrollar": ["Un recorrido de prueba con una o dos personas que no conocen el lugar (o un recorrido propio si no consigues participantes), un conjunto de señales rediseñadas y un prototipo impreso o digital para comprobar si ayudan."], "objetivos": ["Observar dónde y por qué se pierde la gente.", "Diseñar un sistema de señales coherente.", "Probarlo con una o dos personas que no conozcan el espacio o, si no las consigues, haciendo tú mismo el recorrido."], "habilidades": ["Observación", "Diseño gráfico básico", "Pruebas con usuarios"], "herramientas": ["Un editor de diseño", "Planos o croquis del lugar", "Impresiones de prueba"], "lineamientos": ["Pide autorización antes de colocar cualquier prototipo.", "Cuida el contraste y el tamaño de las letras.", "Retira el material al terminar la prueba."], "otroSector": "Sirve para centros de salud, mercados, terminales, bibliotecas o tiendas."}$fc27d33$::jsonb,0),
('un-aviso-antes-de-que-se-eche-a-perder-la-comida','agricultura',array['tecnologia']::text[],'Un aviso antes de que se eche a perder la comida','Imagina cómo utilizar información sencilla para organizar mejor los alimentos almacenados, anticipar fechas importantes y reducir situaciones en las que productos todavía útiles terminan desperdiciándose por falta de seguimiento.','Prototipo','2 a 6 semanas',24,array['Tecnología','Organización','Consumo responsable']::text[],array['crear','resolver','otro-sector']::text[],'ficticios',null,'ingenieria de sistemas ingenieria de software ingenieria industrial ingenieria alimentaria administracion ciencia de datos nutricion logistica organizacion de datos. diseno de inventarios. logica condicional. diseno de interfaces. visualizacion de informacion. analisis basico de procesos. hoja de calculo. herramientas de prototipado. formularios digitales. bases de datos simples. lenguajes de programacion (opcional).',$fe17459${"id": "un-aviso-antes-de-que-se-eche-a-perder-la-comida", "area": "agricultura", "areas2": ["tecnologia"], "titulo": "Un aviso antes de que se eche a perder la comida", "resumen": "Imagina cómo utilizar información sencilla para organizar mejor los alimentos almacenados, anticipar fechas importantes y reducir situaciones en las que productos todavía útiles terminan desperdiciándose por falta de seguimiento.", "tipo": "Prototipo", "tiempo": "2 a 6 semanas", "horas": 24, "etiquetas": ["Tecnología", "Organización", "Consumo responsable"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: puedes hacerlo sin pedir permiso a nadie.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Ingeniería Alimentaria", "Administración", "Ciencia de Datos", "Nutrición", "Logística"], "problema": ["En muchos hogares, pequeños negocios y espacios compartidos se almacenan alimentos que posteriormente se olvidan. Con el paso de los días, algunos productos quedan ocultos detrás de otros, se desconoce cuánto tiempo llevan guardados o simplemente se pierde de vista cuándo deberían consumirse.", "Esta situación no solo genera desperdicio de alimentos. También implica pérdidas económicas, compras innecesarias y una gestión poco eficiente de los recursos disponibles. En algunos casos incluso se vuelven a comprar productos que ya se tenían almacenados porque nadie recuerda que siguen disponibles.", "Aunque existen distintos métodos para organizar inventarios, muchas personas no cuentan con herramientas sencillas que les permitan visualizar qué productos requieren atención primero."], "desarrollar": ["Diseña un inventario digital básico que permita registrar productos, cantidades y fechas relevantes. El sistema debe facilitar la identificación rápida de alimentos que necesitan consumirse pronto mediante indicadores, alertas visuales o niveles de prioridad.", "El prototipo puede desarrollarse mediante una hoja de cálculo, un panel interactivo o una aplicación sencilla."], "ampliaciones": [{"titulo": "Priorizar productos", "aporta": "organiza las alertas según el nivel de urgencia y el tipo de alimento."}, {"titulo": "Analizar desperdicios", "aporta": "estima cuánto alimento y cuánto dinero podría ahorrarse mediante una mejor organización."}, {"titulo": "Diseñar una experiencia móvil", "aporta": "explora cómo consultar la información desde un teléfono para registrar productos en cualquier momento."}], "objetivos": ["Identificar qué información es necesaria para realizar el seguimiento de un alimento.", "Diseñar reglas sencillas para generar alertas útiles.", "Organizar los productos según distintos niveles de prioridad.", "Construir un prototipo funcional utilizando datos simulados.", "Evaluar si el sistema ayuda a visualizar mejor los productos que requieren atención."], "habilidades": ["Organización de datos.", "Diseño de inventarios.", "Lógica condicional.", "Diseño de interfaces.", "Visualización de información.", "Análisis básico de procesos."], "herramientas": ["Hoja de cálculo.", "Herramientas de prototipado.", "Formularios digitales.", "Bases de datos simples.", "Lenguajes de programación (opcional)."], "lineamientos": ["No presentes las alertas como una garantía de seguridad alimentaria. Diferencia claramente las fechas de consumo preferente, vencimiento o caducidad cuando corresponda. Utiliza ejemplos ficticios o escenarios simulados para evitar riesgos asociados al uso de información incorrecta.", "Prioriza que las alertas sean fáciles de entender y no dependan de conocimientos técnicos para ser interpretadas."], "otroSector": "El mismo concepto puede adaptarse al seguimiento de medicamentos sin información de pacientes, materiales de laboratorio, suministros de oficina, herramientas compartidas, repuestos o inventarios básicos de pequeños negocios."}$fe17459$::jsonb,0),
('cuanta-comida-se-tira-en-tu-casa-en-un-mes','agricultura',array['ambiente']::text[],'¿Cuánta comida se tira en tu casa en un mes?','Imagina cómo registrar los alimentos que terminan desechándose para descubrir patrones de consumo, identificar pérdidas evitables y proponer formas de aprovechar mejor los recursos disponibles.','Análisis','~30 h',30,array['Datos','Hogar','Consumo responsable']::text[],array['investigar','resolver','otro-sector']::text[],'propios',null,'ingenieria de sistemas ingenieria industrial ingenieria ambiental estadistica economia nutricion administracion ciencia de datos recoleccion de datos. analisis estadistico basico. diseno de indicadores. visualizacion de informacion. interpretacion de resultados. pensamiento critico. hoja de calculo. formularios digitales. aplicaciones de registro. herramientas de visualizacion de datos.',$fffc93a${"id": "cuanta-comida-se-tira-en-tu-casa-en-un-mes", "area": "agricultura", "areas2": ["ambiente"], "titulo": "¿Cuánta comida se tira en tu casa en un mes?", "resumen": "Imagina cómo registrar los alimentos que terminan desechándose para descubrir patrones de consumo, identificar pérdidas evitables y proponer formas de aprovechar mejor los recursos disponibles.", "tipo": "Análisis", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Datos", "Hogar", "Consumo responsable"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo registres en tu hogar o mediante una simulación documentada.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Ingeniería Ambiental", "Estadística", "Economía", "Nutrición", "Administración", "Ciencia de Datos"], "problema": ["Cada semana se desechan alimentos que podrían haberse consumido. Algunas veces se vencen antes de ser utilizados, otras se compran en exceso o se almacenan de manera inadecuada. Aunque este fenómeno ocurre en muchos hogares, pocas personas llevan un registro que permita comprender cuánto se desperdicia realmente y cuáles son las causas principales.", "La falta de información hace difícil diferenciar entre una impresión y un problema real. Un hogar puede creer que apenas desperdicia comida cuando, acumulando pequeñas pérdidas diarias, termina descartando una cantidad significativa de alimentos a lo largo de un mes.", "Además del impacto económico, el desperdicio alimentario implica un uso innecesario de agua, energía, transporte y otros recursos utilizados durante la producción y distribución de esos alimentos."], "desarrollar": ["Diseña un sistema simple para registrar los alimentos que se descartan durante varias semanas.", "Puedes clasificar los registros según:", {"lista": ["Tipo de alimento.", "Cantidad aproximada.", "Motivo del descarte.", "Fecha de compra.", "Tiempo de almacenamiento."]}, "A partir de esta información, construye gráficos e indicadores que ayuden a identificar patrones y posibles oportunidades de mejora."], "ampliaciones": [{"titulo": "Del registro a la acción", "aporta": "convierte los patrones en un plan semanal de compras y menús, y comprueba si el desperdicio baja."}, {"titulo": "Una mirada más amplia", "aporta": "compara tus resultados con los de otros hogares, con su consentimiento, y descubre qué hábitos cambian más el resultado."}, {"titulo": "Del desperdicio al aprovechamiento", "aporta": "investiga formas de conservación y recetas para los alimentos que más se pierden."}], "objetivos": ["Diseñar una metodología sencilla para registrar desperdicios alimentarios.", "Identificar los productos que se descartan con mayor frecuencia.", "Analizar las causas más comunes del desperdicio.", "Visualizar tendencias mediante gráficos y estadísticas básicas.", "Proponer acciones que permitan reducir pérdidas futuras."], "habilidades": ["Recolección de datos.", "Análisis estadístico básico.", "Diseño de indicadores.", "Visualización de información.", "Interpretación de resultados.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Formularios digitales.", "Aplicaciones de registro.", "Herramientas de visualización de datos."], "lineamientos": ["Mantén criterios consistentes durante todo el periodo de registro. Si realizas estimaciones de cantidades, explica cómo fueron calculadas.", "No es necesario pesar cada alimento con precisión. Lo importante es que los registros sean suficientemente consistentes para identificar tendencias.", "Evita sacar conclusiones apresuradas a partir de pocos días de observación. Cuanto más largo sea el periodo de registro, más útiles serán los resultados."], "otroSector": "La misma metodología puede aplicarse al análisis de desperdicio de agua, energía eléctrica, materiales de oficina, insumos de producción o recursos utilizados en pequeños negocios."}$fffc93a$::jsonb,1),
