-- Proyectos Prácticos — semilla (las otras 11 áreas). Re-ejecutable: si la idea ya existe, la actualiza.
-- Ejecutar DESPUÉS de 01_proyectos_ideas.sql.
on conflict (id) do update set area=excluded.area, areas2=excluded.areas2, titulo=excluded.titulo, resumen=excluded.resumen, tipo=excluded.tipo,
  tiempo=excluded.tiempo, horas=excluded.horas, etiquetas=excluded.etiquetas, intencion=excluded.intencion, datos=excluded.datos, prog=excluded.prog,
  busca=excluded.busca, ficha=excluded.ficha, orden=excluded.orden;
